const lessons = [
  {"num": 2, "time": "00:00:30,000 --> 00:00:33,539", "arabic": "مَنْ فَارَقَ الْجَمَاعَةَ وَالْإِسْلَامَ شِبْرًا", "segs": null, "full_uz": "Kim jamoatdan va islomdan bir qarich ajralsa.", "note": null},
  {"num": 3, "time": "00:00:33,539 --> 00:00:37,219", "arabic": "فَقَدْ خَلَعَ رِبْقَةَ الْإِسْلَامِ مِنْ عُنُقِهِ", "segs": null, "full_uz": "Islom rishtasini bo'ynidan yechib tashlagan bo'ladi.", "note": "«رِبْقَةَ» — bo'yinga solingan bog', rishta ma'nosida."},
  {"num": 4, "time": "00:00:37,219 --> 00:00:42,480", "arabic": "لَقَدْ أَخْطَأْتَ يَا سُهَيْبُ فِي سَنَدِ الْحَدِيثِ", "segs": null, "full_uz": "Sen hadis sanadida xato qilding, ey Suhayb.", "note": null},
  {"num": 5, "time": "00:00:42,480 --> 00:00:47,000", "arabic": "فَهَلْ يَعْرِفُ أَحَدُكُمْ أَيْنَ مَوْطِعُ الْخَطَإِ؟", "segs": null, "full_uz": "Xatoning qayerda ekanini biringiz bilasizmi?", "note": null},
  {"num": 6, "time": "00:00:51,000 --> 00:00:54,260", "arabic": "تَفَضَّلْ يَا ابْنَ حَنْبَلٍ", "segs": null, "full_uz": "Marhamat, Ibn Hanbal.", "note": null},
  {"num": 7, "time": "00:00:54,260 --> 00:00:59,820", "arabic": "أَخِي سُهَيْبٌ أَسْقَطَ مِنَ السَّنَدِ اسْمَ خَالِدِ بْنِ وَهْبَانَ", "segs": [{"ar": "أَخِي سُهَيْبٌ أَسْقَطَ مِنَ السَّنَدِ", "uz": "akam Suhayb sanaddan tushirib qoldirgan"}, {"ar": "اسْمَ خَالِدِ بْنِ وَهْبَانَ", "uz": "Xolid ibn Vahbonning ismini"}], "full_uz": "Akam Suhayb sanaddan Xolid ibn Vahbonning ismini tushirib qoldirgan.", "note": null},
  {"num": 8, "time": "00:01:00,000 --> 00:01:05,760", "arabic": "فَالْحَدِيثُ كَمَا رَوَاهُ أَبُو يُوسُفَ صَاحِبُ أَبِي حَنِيفَةَ النُّعْمَانِ رَحِمَهُمَا اللَّهُ", "segs": [{"ar": "فَالْحَدِيثُ كَمَا رَوَاهُ أَبُو يُوسُفَ", "uz": "hadis Abu Yusuf rivoyat qilganidek"}, {"ar": "صَاحِبُ أَبِي حَنِيفَةَ النُّعْمَانِ رَحِمَهُمَا اللَّهُ", "uz": "Abu Hanifa an-Nu'monning shogirdi, Alloh ikkisiga ham rahmat qilsin"}], "full_uz": "Hadis Abu Hanifa an-Nu'monning shogirdi Abu Yusuf rivoyat qilganidek.", "note": null},
  {"num": 9, "time": "00:01:05,760 --> 00:01:13,599", "arabic": "قَالَ حَدَّثَنِي مُطَرِّفُ بْنُ طَرِيفٍ عَنْ أَبِي الْجَهْمِ عَنْ خَالِدِ بْنِ وَهْبَانَ عَنْ أَبِي ذَرٍّ", "segs": [{"ar": "قَالَ حَدَّثَنِي مُطَرِّفُ بْنُ طَرِيفٍ", "uz": "menga Mutarrif ibn Tarif rivoyat qildi, dedi"}, {"ar": "عَنْ أَبِي الْجَهْمِ عَنْ خَالِدِ بْنِ وَهْبَانَ عَنْ أَبِي ذَرٍّ", "uz": "Abul-Jahm orqali, Xolid ibn Vahbon orqali, Abu Zarrdan"}], "full_uz": "Menga Mutarrif ibn Tarif, Abul-Jahm orqali, Xolid ibn Vahbon orqali, Abu Zarrdan hadis qilib berdi, dedi.", "note": null},
  {"num": 10, "time": "00:01:13,599 --> 00:01:18,760", "arabic": "أَحْسَنْتَ يَا ابْنَ حَنْبَلٍ وَبَارَكَ اللَّهُ فِيكَ", "segs": null, "full_uz": "Barakalla, Ibn Hanbal, Alloh senga barakot bersin.", "note": null},
  {"num": 11, "time": "00:01:18,760 --> 00:01:25,820", "arabic": "حِينَ يَأْتِي أَبُوكَ يَا عُمَيْرُ", "segs": null, "full_uz": "Otang kelganda, ey Umayr.", "note": null},
  {"num": 12, "time": "00:01:25,820 --> 00:01:28,180", "arabic": "قُلْ لَهُ أَنْ يَصْحَبَكَ إِلَى الدُّكَّانِ", "segs": null, "full_uz": "Unga o'zi bilan do'konga olib borishini ayt.", "note": null},
  {"num": 13, "time": "00:01:28,180 --> 00:01:30,840", "arabic": "لِتُصْبِحَ إِسْكَافِيًّا مِثْلَهُ", "segs": null, "full_uz": "Unga o'xshab etikdo'z bo'lishing uchun.", "note": null},
  {"num": 14, "time": "00:01:30,840 --> 00:01:34,980", "arabic": "حِينَ يَأْتِي قُلْ لَهُ ذَلِكَ", "segs": null, "full_uz": "Kelganda, unga shuni ayt.", "note": null},
  {"num": 15, "time": "00:01:34,980 --> 00:01:37,540", "arabic": "إِسْكَافِيًّا مِثْلَ أَبِيكَ", "segs": null, "full_uz": "Otang kabi etikdo'z.", "note": null},
  {"num": 16, "time": "00:01:37,540 --> 00:01:40,640", "arabic": "تَعَالَ إِلَى أُمِّكَ يَا عُمَيْرُ", "segs": null, "full_uz": "Onangning oldiga kel, Umayr.", "note": null},
  {"num": 17, "time": "00:01:40,640 --> 00:01:44,860", "arabic": "عِنْدَمَا يَأْتِي أَبُوكَ", "segs": null, "full_uz": "Otang kelganda.", "note": null},
  {"num": 18, "time": "00:01:44,860 --> 00:01:46,700", "arabic": "قُلْ لَهُ أَنْ يَأْخُذَكَ إِلَى جَدِّكَ", "segs": null, "full_uz": "Unga bobongning oldiga olib borishini ayt.", "note": null},
  {"num": 19, "time": "00:01:46,700 --> 00:01:48,640", "arabic": "لِكَيْ تُصْبِحَ جَزَّارًا مِثْلَهُ", "segs": null, "full_uz": "Unga o'xshab qassob bo'lishing uchun.", "note": null},
  {"num": 20, "time": "00:01:48,640 --> 00:01:52,079", "arabic": "تَعَالَ إِلَى جَدَّتِكَ أَيُّهَا الْإِسْكَافِيُّ الصَّغِيرُ", "segs": null, "full_uz": "Buvingning oldiga kel, kichkina etikdo'z.", "note": null},
  {"num": 21, "time": "00:01:52,079 --> 00:01:56,159", "arabic": "اسْمَعْ كَلَامَ أُمِّكَ أَيُّهَا الْجَزَّارُ الصَّغِيرُ", "segs": null, "full_uz": "Onangning gapiga quloq sol, kichkina qassob.", "note": null},
  {"num": 22, "time": "00:01:56,159 --> 00:01:57,519", "arabic": "إِسْكَافِيٌّ", "segs": null, "full_uz": "Etikdo'z.", "note": null},
  {"num": 23, "time": "00:01:57,519 --> 00:01:58,799", "arabic": "بَلْ جَزَّارٌ", "segs": null, "full_uz": "Yo'q, qassob.", "note": null},
  {"num": 24, "time": "00:01:58,799 --> 00:02:00,019", "arabic": "بَلْ إِسْكَافِيٌّ", "segs": null, "full_uz": "Yo'q, etikdo'z.", "note": null},
  {"num": 25, "time": "00:02:00,019 --> 00:02:01,239", "arabic": "قُلْتُ لَكَ جَزَّارٌ", "segs": null, "full_uz": "Senga qassob dedim-ku.", "note": null},
  {"num": 26, "time": "00:02:01,239 --> 00:02:02,540", "arabic": "قَبَّحَكَ اللَّهُ", "segs": null, "full_uz": "Alloh seni la'natlasin!", "note": "«قَبَّحَكَ اللَّهُ» — g'azab bildiruvchi qarg'ish ibora."},
  {"num": 27, "time": "00:02:02,540 --> 00:02:03,900", "arabic": "اِفْتَحِ الْبَابَ لِزَوْجِكِ", "segs": null, "full_uz": "Eshikni eringga och.", "note": null},
  {"num": 28, "time": "00:02:03,900 --> 00:02:05,640", "arabic": "اِفْتَحِ الْبَابَ لِابْنِكِ", "segs": null, "full_uz": "Eshikni o'g'lingga och.", "note": null},
  {"num": 30, "time": "00:02:18,639 --> 00:02:20,439", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
  {"num": 31, "time": "00:02:20,439 --> 00:02:22,759", "arabic": "أَهْلًا يَا قُرَّةَ عَيْنِ أُمِّكَ", "segs": null, "full_uz": "Xush kelibsan, onangning ko'z nuri.", "note": null},
  {"num": 32, "time": "00:02:22,759 --> 00:02:23,359", "arabic": "عُمَيْرُ", "segs": null, "full_uz": "Umayr!", "note": null},
  {"num": 34, "time": "00:02:24,759 --> 00:02:26,139", "arabic": "تَعَالَ يَا عُمَيْرُ", "segs": null, "full_uz": "Kel, Umayr.", "note": null},
  {"num": 35, "time": "00:02:26,139 --> 00:02:28,479", "arabic": "تَعَالَ يَا حَبِيبِي", "segs": null, "full_uz": "Kel, azizim.", "note": null},
  {"num": 37, "time": "00:02:31,439 --> 00:02:34,479", "arabic": "اِسْمَعْ يَا عُمَيْرُ أُرِيدُكَ أَنْ تُصْبِحَ عَالِمًا", "segs": [{"ar": "اِسْمَعْ يَا عُمَيْرُ", "uz": "eshit, Umayr"}, {"ar": "أُرِيدُكَ أَنْ تُصْبِحَ عَالِمًا", "uz": "men seni olim bo'lishingni istayman"}], "full_uz": "Eshit, Umayr, men seni olim bo'lishingni istayman.", "note": null},
  {"num": 38, "time": "00:02:34,479 --> 00:02:36,859", "arabic": "قُلْ لِي لِمَاذَا تَبْكِي أُمُّكَ؟", "segs": null, "full_uz": "Ayt-chi, onang nega yig'layapti?", "note": null},
  {"num": 39, "time": "00:02:36,859 --> 00:02:38,060", "arabic": "هَلْ ضَرَبَتْهَا جَدَّتُكَ؟", "segs": null, "full_uz": "Uni buving urdimi?", "note": null},
  {"num": 40, "time": "00:02:38,060 --> 00:02:38,339", "arabic": "لَا", "segs": null, "full_uz": "Yo'q.", "note": null},
  {"num": 41, "time": "00:02:38,339 --> 00:02:40,439", "arabic": "تَشَاجَرَتْ مَعَهَا؟", "segs": null, "full_uz": "U bilan janjallashdimi?", "note": null},
  {"num": 42, "time": "00:02:40,439 --> 00:02:40,719", "arabic": "لَا", "segs": null, "full_uz": "Yo'q.", "note": null},
  {"num": 43, "time": "00:02:40,719 --> 00:02:42,639", "arabic": "مَاتَ أَبُوهَا الْجَزَّارُ؟", "segs": null, "full_uz": "Uning otasi qassob vafot etdimi?", "note": null},
  {"num": 44, "time": "00:02:44,659 --> 00:02:45,000", "arabic": "لَا", "segs": null, "full_uz": "Yo'q.", "note": null},
  {"num": 45, "time": "00:02:45,000 --> 00:02:45,639", "arabic": "مَاذَا؟", "segs": null, "full_uz": "Nima bo'ldi?", "note": null},
  {"num": 46, "time": "00:02:45,639 --> 00:02:48,639", "arabic": "أَتَرْجُو الْمَوْتَ لِأَبِي عَامِرٍ؟", "segs": null, "full_uz": "Abu Omirga o'lim tilayapsanmi?", "note": null},
  {"num": 47, "time": "00:02:48,639 --> 00:02:51,639", "arabic": "زَوْجَتِي، الْمَوْتُ لَا يَتْرُكُ وَاحِدًا", "segs": [{"ar": "زَوْجَتِي", "uz": "xotinim"}, {"ar": "الْمَوْتُ لَا يَتْرُكُ وَاحِدًا", "uz": "o'lim hech kimni qo'ymaydi"}], "full_uz": "Xotinim, o'lim hech kimni qo'ymaydi.", "note": null},
  {"num": 48, "time": "00:02:51,639 --> 00:02:53,639", "arabic": "قُولِي لِي لِمَاذَا تَبْكِينَ؟", "segs": null, "full_uz": "Ayt-chi, nega yig'layapsan?", "note": null},
  {"num": 49, "time": "00:02:53,639 --> 00:02:56,639", "arabic": "زَوْجَتُكَ تُرِيدُ لِعُمَيْرَ أَنْ يُصْبِحَ جَزَّارًا", "segs": null, "full_uz": "Xotining Umayrning qassob bo'lishini xohlaydi.", "note": null},
  {"num": 50, "time": "00:02:56,639 --> 00:02:59,639", "arabic": "وَأُمُّكَ تُرِيدُهُ إِسْكَافِيًّا", "segs": null, "full_uz": "Onang esa uni etikdo'z bo'lishini xohlaydi.", "note": null},
  {"num": 51, "time": "00:02:59,639 --> 00:03:02,639", "arabic": "هَلْ نَنْتَهِي مِنْ هَذَا الصِّرَاعِ؟", "segs": null, "full_uz": "Bu janjaldan qutulamizmi?", "note": null},
  {"num": 52, "time": "00:03:02,639 --> 00:03:04,639", "arabic": "هَلْ نَنْتَهِي مِنْ هَذَا الصِّرَاعِ وَالْجِدَالِ يَا أُمِّي؟", "segs": null, "full_uz": "Bu janjal va tortishuvdan qutulamizmi, onajon?", "note": null},
  {"num": 53, "time": "00:03:04,639 --> 00:03:09,639", "arabic": "كُلَّمَا أَتَيْتُ إِلَى الْبَيْتِ تَبْدَأُ مَسِيرَةُ الْبُكَاءِ وَالنَّوَاحِ وَاللَّطْمِ وَالصِّيَاحِ", "segs": [{"ar": "كُلَّمَا أَتَيْتُ إِلَى الْبَيْتِ", "uz": "uyga har kelganimda"}, {"ar": "تَبْدَأُ مَسِيرَةُ الْبُكَاءِ وَالنَّوَاحِ وَاللَّطْمِ وَالصِّيَاحِ", "uz": "yig'i, nola, yuz urish va qichqiriq boshlanadi"}], "full_uz": "Uyga har kelganimda yig'i, nola, yuz urish va qichqiriq boshlanadi.", "note": null},
  {"num": 54, "time": "00:03:09,639 --> 00:03:12,639", "arabic": "لَا إِسْكَافِيَّ وَلَا جَزَّارَ", "segs": null, "full_uz": "Na etikdo'z, na qassob.", "note": null},
  {"num": 55, "time": "00:03:12,639 --> 00:03:16,419", "arabic": "لَا هَذَا وَلَا ذَاكَ", "segs": null, "full_uz": "Na bu, na u.", "note": null},
  {"num": 56, "time": "00:03:16,419 --> 00:03:20,759", "arabic": "سَأُرْسِلُهُ إِلَى الْكُتَّابِ يَتَعَلَّمُ الْقُرْآنَ وَالْحَدِيثَ", "segs": null, "full_uz": "Uni maktabga yuboraman, Qur'on va hadis o'rgansin.", "note": "«الْكُتَّابِ» — an'anaviy diniy boshlang'ich maktab (kuttob)."},
  {"num": 57, "time": "00:03:20,759 --> 00:03:22,219", "arabic": "مَاذَا؟", "segs": null, "full_uz": "Nima?", "note": null},
  {"num": 58, "time": "00:03:22,219 --> 00:03:25,759", "arabic": "هَلْ تُرِيدُهُ أَنْ يُصْبِحَ قَاضِيًا كَقَاضِي بَغْدَادَ؟", "segs": null, "full_uz": "Uni Bag'dod qozisiga o'xshab qozi bo'lishini xohlaysanmi?", "note": null},
  {"num": 59, "time": "00:03:25,759 --> 00:03:28,839", "arabic": "أَمْ سَيُصْبِحُ مِثْلَ الْإِمَامِ أَبِي حَنِيفَةَ النُّعْمَانِ؟", "segs": null, "full_uz": "Yoki imom Abu Hanifa an-Nu'monga o'xshab bo'ladimi?", "note": null},
  {"num": 60, "time": "00:03:28,839 --> 00:03:29,979", "arabic": "اِتَّفَقْتُمَا الْآنَ", "segs": null, "full_uz": "Hozir kelishib oldinglarmi.", "note": null},
  {"num": 61, "time": "00:03:29,979 --> 00:03:31,419", "arabic": "اِتَّفَقْتُمَا؟", "segs": null, "full_uz": "Kelishib oldinglarmi?", "note": null},
  {"num": 62, "time": "00:03:31,419 --> 00:03:32,079", "arabic": "اِسْمَعَا", "segs": null, "full_uz": "Ikkovingiz eshiting.", "note": null},
  {"num": 63, "time": "00:03:32,079 --> 00:03:37,579", "arabic": "أَنَا مُصِرٌّ عَلَى إِرْسَالِهِ إِلَى الْكُتَّابِ يَتَعَلَّمُ الْقُرْآنَ وَالْحَدِيثَ", "segs": [{"ar": "أَنَا مُصِرٌّ عَلَى إِرْسَالِهِ إِلَى الْكُتَّابِ", "uz": "men uni kuttobga yuborishga qat'iy qaror qildim"}, {"ar": "يَتَعَلَّمُ الْقُرْآنَ وَالْحَدِيثَ", "uz": "Qur'on va hadis o'rgansin"}], "full_uz": "Men uni kuttobga yuborishga qat'iy qaror qildim, Qur'on va hadis o'rgansin.", "note": null},
  {"num": 64, "time": "00:03:37,580 --> 00:03:40,680", "arabic": "بَيْتُ الْعَالِمِ", "segs": null, "full_uz": "Olimning uyi.", "note": null},
  {"num": 65, "time": "00:03:40,680 --> 00:03:42,740", "arabic": "عُمَيْرُ بْنُ عَامِرٍ", "segs": null, "full_uz": "Umayr ibn Omir.", "note": null},
  {"num": 67, "time": "00:03:43,480 --> 00:03:44,840", "arabic": "أُمُّ الْعَالِمِ", "segs": null, "full_uz": "Olimning onasi.", "note": null},
  {"num": 68, "time": "00:03:44,840 --> 00:03:46,220", "arabic": "جَدَّةُ الْعَالِمِ", "segs": null, "full_uz": "Olimning buvisi.", "note": null},
  {"num": 69, "time": "00:03:46,220 --> 00:03:47,060", "arabic": "أَبُو الْعَالِمِ", "segs": null, "full_uz": "Olimning otasi.", "note": null},
  {"num": 70, "time": "00:03:47,060 --> 00:03:48,220", "arabic": "عَائِلَةُ الْعَالِمِ", "segs": null, "full_uz": "Olimning oilasi.", "note": null},
  {"num": 75, "time": "00:04:37,579 --> 00:04:59,479", "arabic": "الْحَمْدُ لِلَّهِ الَّذِي أَرَاحَنِي مِنْ هَذَا الْمُكْتَرِي", "segs": [{"ar": "الْحَمْدُ لِلَّهِ", "uz": "Allohga hamd bo'lsin"}, {"ar": "الَّذِي أَرَاحَنِي مِنْ هَذَا الْمُكْتَرِي", "uz": "meni bu ijarachidan qutqargan"}], "full_uz": "Meni bu ijarachidan qutqargan Allohga hamdlar bo'lsin.", "note": null},
  {"num": 76, "time": "00:04:59,479 --> 00:05:02,259", "arabic": "لَقَدْ أَرْهَقَنِي لَوْمُ الْجِيرَانِ بِسَبَبِهِ", "segs": null, "full_uz": "Uning sababidan qo'shnilarning malomati meni charchatib yubordi.", "note": null},
  {"num": 77, "time": "00:05:02,259 --> 00:05:03,659", "arabic": "أَيْنَ ذَهَبَ؟", "segs": null, "full_uz": "U qayerga ketdi?", "note": null},
  {"num": 78, "time": "00:05:03,659 --> 00:05:05,620", "arabic": "لَا أَدْرِي عَلَى أَيِّ حَالٍ", "segs": null, "full_uz": "Bilmayman, baribir.", "note": null},
  {"num": 79, "time": "00:05:05,620 --> 00:05:09,340", "arabic": "يَبْدُو أَنَّنِي لَنْ أُؤَجِّرَ هَذَا الْبَيْتَ بَعْدَ الْيَوْمِ", "segs": null, "full_uz": "Ko'rinishidan, bundan buyon bu uyni ijaraga bermayman.", "note": null},
  {"num": 80, "time": "00:05:09,340 --> 00:05:11,920", "arabic": "إِلَّا لِرَجُلٍ يَأْتِي بِشَاهِدَيْ عَدْلٍ", "segs": null, "full_uz": "Faqat ikkita adolatli guvoh olib kelgan odamga beraman.", "note": null},
  {"num": 81, "time": "00:05:11,920 --> 00:05:14,660", "arabic": "كَانَ اللَّهُ فِي عَوْنِكَ يَا ابْنَ نُوحٍ", "segs": null, "full_uz": "Alloh sizga yordamchi bo'lsin, ey Ibn Nuh.", "note": null},
  {"num": 82, "time": "00:05:14,660 --> 00:05:16,780", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا أَنْتَ", "segs": null, "full_uz": "Kuch-quvvat faqat sendandir.", "note": "Mashhur ibora odatda «لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ» shaklida bo'ladi; bu yerda o'zgacharoq aytilgan."},
  {"num": 83, "time": "00:05:16,780 --> 00:05:17,540", "arabic": "أَنْتَ يَا ابْنَ حَنْبَلٍ", "segs": null, "full_uz": "Sen-a, Ibn Hanbal.", "note": null},
  {"num": 84, "time": "00:05:17,540 --> 00:05:25,040", "arabic": "لِمَاذَا لَا تَكُفُّ عَنِ التَّكَبُّرِ وَالتَّعَالِي عَلَيَّ؟", "segs": null, "full_uz": "Nega menga takabburlik va manmanlik qilishni to'xtatmaysan?", "note": null},
  {"num": 85, "time": "00:05:25,040 --> 00:05:27,879", "arabic": "وَفِيمَ تَكَبَّرْتُ أَوْ تَعَالَيْتُ عَلَيْكَ؟", "segs": null, "full_uz": "Men senga qachon takabburlik yoki manmanlik qildim?", "note": null},
  {"num": 86, "time": "00:05:27,879 --> 00:05:31,660", "arabic": "مَنْ تَحْسَبُ نَفْسَكَ حَتَّى تُصَوِّبَ لِي كَلَامِي أَمَامَ الشَّيْخِ؟", "segs": null, "full_uz": "Shayx oldida gapimni to'g'rilashga o'zingni kim deb bilasan?", "note": null},
  {"num": 87, "time": "00:05:31,660 --> 00:05:37,180", "arabic": "أَمْ أَنَّكَ نَسِيتَ مَنْ أَنَا وَمَنْ أَنْتَ؟", "segs": null, "full_uz": "Yoki men kimligimni, sen kimligingni unutdingmi?", "note": null},
  {"num": 88, "time": "00:05:37,180 --> 00:05:43,620", "arabic": "اِسْمَعْ يَا أَخِي", "segs": null, "full_uz": "Eshit, ukam.", "note": null},
  {"num": 89, "time": "00:05:43,620 --> 00:05:47,980", "arabic": "إِنْ كُنْتَ تَظُنُّ أَنِّي نِلْتُ مِنْكَ بِمَسَاءَةٍ فَأَنَا أَعْتَذِرُ إِلَيْكَ", "segs": [{"ar": "إِنْ كُنْتَ تَظُنُّ أَنِّي نِلْتُ مِنْكَ بِمَسَاءَةٍ", "uz": "agar sendan yomonlik bilan gapirdim deb o'ylasang"}, {"ar": "فَأَنَا أَعْتَذِرُ إِلَيْكَ", "uz": "sendan uzr so'rayman"}], "full_uz": "Agar sendan yomonlik bilan gapirdim deb o'ylasang, sendan uzr so'rayman.", "note": null},
  {"num": 90, "time": "00:05:47,980 --> 00:05:53,200", "arabic": "وَلَكِنْ يَجِبُ أَنْ تَعْلَمَ أَنَّ هَذَا الْعِلْمَ دِينٌ وَدِينُ اللَّهِ لَا مُجَامَلَةَ فِيهِ", "segs": [{"ar": "وَلَكِنْ يَجِبُ أَنْ تَعْلَمَ أَنَّ هَذَا الْعِلْمَ دِينٌ", "uz": "lekin bilishing kerakki, bu ilm dindir"}, {"ar": "وَدِينُ اللَّهِ لَا مُجَامَلَةَ فِيهِ", "uz": "Alloh dinida esa murosa yo'q"}], "full_uz": "Lekin bilishing kerakki, bu ilm dindir, Alloh dinida esa murosa yo'q.", "note": null},
  {"num": 91, "time": "00:05:54,340 --> 00:05:56,180", "arabic": "أَمَّا الْأُخْرَى يَا صُهَيْبُ", "segs": null, "full_uz": "Ikkinchi masalaga kelsak, ey Suhayb.", "note": null},
  {"num": 92, "time": "00:05:56,180 --> 00:06:00,020", "arabic": "فَالنَّاسُ لَا يَتَفَاضَلُونَ عِنْدَ اللَّهِ إِلَّا فِي التَّقْوَى", "segs": null, "full_uz": "Odamlar Alloh huzurida faqat taqvo bilan bir-biridan ustun bo'ladi.", "note": null},
  {"num": 93, "time": "00:06:00,019 --> 00:06:05,659", "arabic": "وَمَا يَضِيرُكَ أَنْ تَسْكُتَ؟", "segs": null, "full_uz": "Sukut qilsang senga nima zarar?", "note": null},
  {"num": 94, "time": "00:06:05,659 --> 00:06:08,659", "arabic": "أَمْ أَنَّكَ تَنْتَهِزُ أَيَّ فُرْصَةٍ لِلنَّيْلِ مِنِّي؟", "segs": null, "full_uz": "Yoki mendan qasos olish uchun har qanday fursatdan foydalanyapsanmi?", "note": null},
  {"num": 95, "time": "00:06:09,519 --> 00:06:13,759", "arabic": "لَا أَسْكُتُ عَنْ خَطَإٍ وَقَعَ مَهْمَا حَدَثَ", "segs": null, "full_uz": "Nima bo'lishidan qat'i nazar, sodir bo'lgan xato haqida sukut qilmayman.", "note": null},
  {"num": 96, "time": "00:06:13,759 --> 00:06:18,519", "arabic": "وَشَيْخُنَا مَنْ طَلَبَ مِنِّي أَنْ نُصَوِّبَ الْخَطَأَ الَّذِي وَقَعْتَ أَنْتَ فِيهِ", "segs": null, "full_uz": "Sen tushib qolgan xatoni to'g'rilashimni ustozimiz o'zi mendan so'ragan.", "note": null},
  {"num": 97, "time": "00:06:18,519 --> 00:06:22,659", "arabic": "وَمَا فَعَلْتُ إِلَّا وَاجِبِي وَمَا طَلَبَهُ شَيْخِي وَشَيْخُكَ", "segs": null, "full_uz": "Men faqat o'z vazifamni va ustozim — sening ham ustozing — talab qilgan narsani bajardim.", "note": null},
  {"num": 98, "time": "00:06:22,659 --> 00:06:27,659", "arabic": "أُقْسِمُ لَتَدْفَعَنَّ لَنَا الثَّمَنَ غَالِيًا يَا ابْنَ حَنْبَلٍ", "segs": null, "full_uz": "Qasamki, buning qimmat bahosini to'laysan, ey Ibn Hanbal.", "note": null},
  {"num": 100, "time": "00:06:33,519 --> 00:06:49,019", "arabic": "مَنْ مِنْكُمْ يُنْكِرُ مَا نُسِبَ إِلَيْهِ مِنَ الْخُرُوجِ عَلَى طَاعَةِ أَمِيرِ الْمُؤْمِنِينَ؟", "segs": [{"ar": "مَنْ مِنْكُمْ يُنْكِرُ مَا نُسِبَ إِلَيْهِ", "uz": "sizlardan kim o'ziga nisbat berilgan narsani inkor qiladi"}, {"ar": "مِنَ الْخُرُوجِ عَلَى طَاعَةِ أَمِيرِ الْمُؤْمِنِينَ؟", "uz": "mo'minlar amiriga itoatdan chiqqanlik haqidagi (ayb)dan"}], "full_uz": "Sizlardan kim mo'minlar amiriga itoatdan chiqqanlikda ayblanganini inkor qiladi?", "note": null},
  {"num": 101, "time": "00:06:51,079 --> 00:06:52,019", "arabic": "أَنَا أَمِيرُ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Men mo'minlar amiriman.", "note": null},
  {"num": 102, "time": "00:06:52,659 --> 00:06:56,079", "arabic": "أَنَا وَتَلَامِذَتِي", "segs": null, "full_uz": "Men va shogirdlarim.", "note": null},
  {"num": 103, "time": "00:06:56,079 --> 00:07:01,120", "arabic": "لَمْ وَلَنْ نَخْرُجَ عَنْ طَاعَةِ وَلِيِّ أَمْرِ الْمُؤْمِنِينَ يَوْمًا", "segs": null, "full_uz": "Biz mo'minlarning hukmdoriga itoatdan hech qachon chiqmaganmiz va chiqmaymiz ham.", "note": null},
  {"num": 104, "time": "00:07:01,120 --> 00:07:05,259", "arabic": "مَادَامَ يَحْكُمُ بِشَرْعِ اللَّهِ عَزَّ وَجَلَّ", "segs": null, "full_uz": "Toki u Alloh taologning shariati bilan hukm qilar ekan.", "note": null},
  {"num": 105, "time": "00:07:05,259 --> 00:07:09,159", "arabic": "وَسُنَّةِ نَبِيِّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "segs": null, "full_uz": "Va payg'ambari (Allohning salovoti va salomi bo'lsin) sunnati bilan.", "note": null},
  {"num": 106, "time": "00:07:09,159 --> 00:07:11,279", "arabic": "صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "segs": null, "full_uz": "Allohning salovoti va salomi u zotga bo'lsin.", "note": null},
  {"num": 107, "time": "00:07:11,279 --> 00:07:15,139", "arabic": "حَتَّى لَا يُظْلَمَ أَحَدٌ عِنْدِي", "segs": null, "full_uz": "Toki huzurimda hech kimga zulm qilinmasin.", "note": null},
  {"num": 108, "time": "00:07:15,139 --> 00:07:18,159", "arabic": "سَتُعْرَضُونَ عَلَى الْقَضَاءِ", "segs": null, "full_uz": "Sizlar sudga (qoziga) taqdim etilasizlar.", "note": null},
  {"num": 109, "time": "00:07:18,159 --> 00:07:20,740", "arabic": "وَلِلْقَضَاءِ الْكَلِمَةُ الْفَصْلُ", "segs": null, "full_uz": "Va hal qiluvchi so'z sudnikidir.", "note": null},
  {"num": 110, "time": "00:07:20,740 --> 00:07:22,819", "arabic": "خُذْهُمْ يَا مَسْرُورُ", "segs": null, "full_uz": "Ularni olib ket, ey Masrur.", "note": null},
  {"num": 111, "time": "00:07:22,819 --> 00:07:24,860", "arabic": "اَلسَّمْعُ وَالطَّاعَةُ يَا مَوْلَايَ", "segs": null, "full_uz": "Eshitdik va bo'ysunamiz, xo'jayinim.", "note": null},
  {"num": 112, "time": "00:07:24,860 --> 00:07:26,220", "arabic": "هَيَّا", "segs": null, "full_uz": "Yur, tezroq.", "note": null},
  {"num": 115, "time": "00:07:32,020 --> 00:07:33,540", "arabic": "هَيَّا", "segs": null, "full_uz": "Yur, tezroq.", "note": null},
  {"num": 116, "time": "00:07:33,540 --> 00:07:45,620", "arabic": "أُقْسِمُ لَا تَدْفَعُ لَنَا الثَّمَنَ غَالِيًا يَا ابْنَ حَنْبَلٍ", "segs": null, "full_uz": "Qasamki, buning qimmat bahosini to'laysan, ey Ibn Hanbal.", "note": null},
  {"num": 117, "time": "00:07:45,620 --> 00:07:49,840", "arabic": "وَأُقْسِمُ إِنْ عُدْتَ لِمِثْلِهَا", "segs": null, "full_uz": "Yana shunga o'xshagan ishni qaytarsang, qasam ichamanki...", "note": null},
  {"num": 119, "time": "00:07:51,439 --> 00:07:55,060", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "segs": null, "full_uz": "Kuch-quvvat faqat Alloh bilandir.", "note": null},
  {"num": 120, "time": "00:07:55,060 --> 00:07:56,379", "arabic": "وَأَسْتَغْفِرُ اللَّهَ عَلَى هَذَيْنِ", "segs": null, "full_uz": "Bu ikkisi uchun Allohdan mag'firat so'rayman.", "note": null},
  {"num": 121, "time": "00:07:56,379 --> 00:08:00,240", "arabic": "اَللَّهُمَّ لَا تَجْعَلْنَا مِمَّنْ قُلْتَ فِيهِمْ", "segs": null, "full_uz": "Ey Alloh, bizni Sen aytgan kishilardan qilma.", "note": null},
  {"num": 122, "time": "00:08:00,240 --> 00:08:03,339", "arabic": "وَجَعَلْنَا بَعْضَكُمْ لِبَعْضٍ فِتْنَةً", "segs": null, "full_uz": "Va ba'zilaringizni ba'zilaringiz uchun sinov qildik.", "note": "Qur'ondagi (Furqon, 20-oyat) iqtibos."},
  {"num": 123, "time": "00:08:03,339 --> 00:08:06,519", "arabic": "أَتَصْبِرُونَ وَكَانَ رَبُّكَ بَصِيرًا", "segs": null, "full_uz": "Sabr qilarmisizlar? Parvardigoring hamma narsani ko'rib turuvchidir.", "note": null},
  {"num": 124, "time": "00:08:06,519 --> 00:08:09,899", "arabic": "بَلِ اجْعَلْنَا مِمَّنْ قُلْتَ فِيهِمْ", "segs": null, "full_uz": "Balki bizni Sen aytgan (boshqa) kishilardan qilgin.", "note": null},
  {"num": 125, "time": "00:08:09,899 --> 00:08:12,560", "arabic": "وَنَزَعْنَا مَا فِي صُدُورِهِمْ مِنْ غِلٍّ", "segs": null, "full_uz": "Va ularning ko'ngillaridagi kin-adovatni yulib oldik.", "note": "Qur'ondagi (Hijr, 47-oyat) iqtibos."},
  {"num": 126, "time": "00:08:12,560 --> 00:08:14,600", "arabic": "إِخْوَانًا", "segs": null, "full_uz": "Birodar bo'lgan holda.", "note": null},
  {"num": 127, "time": "00:08:21,439 --> 00:08:22,399", "arabic": "تَفَضَّلْ", "segs": null, "full_uz": "Marhamat, kiring.", "note": null},
  {"num": 128, "time": "00:08:22,399 --> 00:08:28,699", "arabic": "إِنَّكَ فَتًى ذَكِيٌّ يَا فَرَجُ", "segs": null, "full_uz": "Sen aqlli yigitsan, Faraj.", "note": null},
  {"num": 129, "time": "00:08:28,699 --> 00:08:33,259", "arabic": "فَقَدِ اسْتَطَعْتَ فِي فَتْرَةٍ وَجِيزَةٍ أَنْ تُصْبِحَ مِنْ خِيَرَةِ الصَّالِحِينَ", "segs": null, "full_uz": "Qisqa muddat ichida solih kishilarning eng yaxshilaridan biriga aylanding.", "note": null},
  {"num": 130, "time": "00:08:33,259 --> 00:08:36,360", "arabic": "حَتَّى أَنَّكَ تَفَوَّقْتَ عَلَى مُعَلِّمِكَ بَزَّالَ", "segs": null, "full_uz": "Hatto ustozing Bazzaldan ham o'zib ketding.", "note": null},
  {"num": 131, "time": "00:08:36,360 --> 00:08:38,299", "arabic": "يَا بُسْرُحَانُ", "segs": null, "full_uz": "Ey Busruhon!", "note": null},
  {"num": 132, "time": "00:08:38,299 --> 00:08:40,539", "arabic": "أَيُّ ذَكَاءٍ", "segs": null, "full_uz": "Naqadar aqllilik!", "note": null},
  {"num": 133, "time": "00:08:40,539 --> 00:08:45,500", "arabic": "هَا أَنَا ذَا فِي هَذِهِ الدُّكَّانِ مُنْذُ سِنِينَ وَلَمْ أَسْتَطِعْ أَنْ أَجْمَعَ دِرْهَمًا وَاحِدًا", "segs": [{"ar": "هَا أَنَا ذَا فِي هَذِهِ الدُّكَّانِ مُنْذُ سِنِينَ", "uz": "mana, men necha yildan beri shu do'konda"}, {"ar": "وَلَمْ أَسْتَطِعْ أَنْ أَجْمَعَ دِرْهَمًا وَاحِدًا", "uz": "bir dirham ham jamg'ara olmadim"}], "full_uz": "Mana, men necha yildan beri shu do'konda bo'lsam ham, bir dirham ham jamg'ara olmadim.", "note": null},
  {"num": 134, "time": "00:08:45,500 --> 00:08:48,840", "arabic": "أَيُّ ذَكَاءٍ فِي أَنْ يَقْضِيَ الْمَرْءُ عُمْرَهُ يَرْكُضُ", "segs": null, "full_uz": "Odam butun umrini yugurib o'tkazishida qanday aqllilik bor?", "note": null},
  {"num": 135, "time": "00:08:48,840 --> 00:08:51,740", "arabic": "وَلَا يَرْجِعُ فِي آخِرِ الْيَوْمِ إِلَّا بِمَا يَسُدُّ رَمَقَهُ", "segs": null, "full_uz": "Kun oxirida faqat qornini to'ydiradigan narsa bilan qaytadi.", "note": null},
  {"num": 138, "time": "00:09:01,280 --> 00:09:02,840", "arabic": "هَلْ وَجَدْتَ سِوَاهُ؟", "segs": null, "full_uz": "Undan boshqasini topdingmi?", "note": null},
  {"num": 139, "time": "00:09:04,019 --> 00:09:04,940", "arabic": "اَلْأَعْمَالُ كَثِيرَةٌ", "segs": null, "full_uz": "Ishlar ko'p.", "note": null},
  {"num": 141, "time": "00:09:07,320 --> 00:09:08,860", "arabic": "اَلْأَعْمَالُ كَثِيرَةٌ؟", "segs": null, "full_uz": "Ishlar ko'pmi?", "note": null},
  {"num": 142, "time": "00:09:08,860 --> 00:09:11,540", "arabic": "أَعْطِنِي عَمَلًا وَاحِدًا يَزِيدُ عَائِدُهُ عَنْ عَائِدِ عَمَلِي", "segs": null, "full_uz": "Menga daromadi mening ishimning daromadidan ko'p bo'lgan bitta ish bering.", "note": null},
  {"num": 144, "time": "00:09:18,840 --> 00:09:28,060", "arabic": "هَلْ يَلِيقُ بِي أَنْ أُمْسِكَ لِسَانِي عَنْ خَطَإٍ فِي رِوَايَةِ حَدِيثٍ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "segs": [{"ar": "هَلْ يَلِيقُ بِي أَنْ أُمْسِكَ لِسَانِي عَنْ خَطَإٍ", "uz": "xatoga nisbatan tilimni tiyib turishim menga to'g'ri keladimi"}, {"ar": "فِي رِوَايَةِ حَدِيثٍ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "uz": "Rasululloh sollallohu alayhi va sallamning hadisini rivoyat qilishda"}], "full_uz": "Rasululloh (sollallohu alayhi va sallam)ning hadisini rivoyat qilishdagi xatoga nisbatan tilimni tiyib turishim menga munosibmi?", "note": null},
  {"num": 145, "time": "00:09:28,060 --> 00:09:29,460", "arabic": "حَتَّى يَرْضَى صُهَيْبٌ", "segs": null, "full_uz": "Suhayb rozi bo'lguncha.", "note": null},
  {"num": 146, "time": "00:09:29,460 --> 00:09:32,399", "arabic": "أَعْلَمُ أَنَّكَ لَسْتَ بِمَلُومٍ عَلَى ذَلِكَ يَا أَبَا عَبْدِ اللَّهِ", "segs": null, "full_uz": "Bilaman, sen buning uchun ayblanmaysan, ey Abu Abdulloh.", "note": null},
  {"num": 147, "time": "00:09:32,399 --> 00:09:37,700", "arabic": "وَلَكِنَّ صُهَيْبًا غَفَرَ اللَّهُ لَهُ أَسَاءَ التَّصَرُّفَ وَاسْتَعْجَلَ الرَّدَّ", "segs": null, "full_uz": "Lekin Suhayb — Alloh uni mag'firat qilsin — noto'g'ri xatti-harakat qildi va javobda shoshildi.", "note": null},
  {"num": 148, "time": "00:09:37,700 --> 00:09:45,879", "arabic": "إِنَّمَا الْمُؤْمِنُونَ إِخْوَةٌ وَيَجِبُ أَلَّا تَسْمَحَ لِمَسْأَلَةٍ صَغِيرَةٍ عَابِرَةٍ مِثْلِ هَذِهِ أَنْ تُفْقِدَكَ حِلْمَكَ وَأَنَاتَكَ", "segs": [{"ar": "إِنَّمَا الْمُؤْمِنُونَ إِخْوَةٌ", "uz": "mo'minlar faqat birodardirlar"}, {"ar": "وَيَجِبُ أَلَّا تَسْمَحَ لِمَسْأَلَةٍ صَغِيرَةٍ عَابِرَةٍ مِثْلِ هَذِهِ", "uz": "shunga o'xshash kichik, o'tkinchi masalaga yo'l qo'ymasliging kerak"}, {"ar": "أَنْ تُفْقِدَكَ حِلْمَكَ وَأَنَاتَكَ", "uz": "seni yumshoqlik va sabringdan mahrum qilsin"}], "full_uz": "Mo'minlar faqat birodardirlar, shunga o'xshash kichik, o'tkinchi masala seni yumshoqlik va sabringdan mahrum qilishiga yo'l qo'ymasliging kerak.", "note": null},
  {"num": 149, "time": "00:09:45,879 --> 00:09:50,740", "arabic": "يَا بَدْرُ أَنْتَ تَعْلَمُ أَنَّ هَذَا الْعِلْمَ الَّذِي نَطْلُبُهُ لَيْسَ كَغَيْرِهِ مِنَ الْعُلُومِ", "segs": null, "full_uz": "Ey Badr, bilasanki, biz talab qilayotgan bu ilm boshqa ilmlarga o'xshamaydi.", "note": null},
  {"num": 150, "time": "00:09:50,740 --> 00:09:55,259", "arabic": "وَأَنْتَ تَرَى حَوْلَكَ كَثْرَةَ الْوَضَّاعِينَ وَالْمُدَلِّسِينَ فِي حَدِيثِ رَسُولِ اللَّهِ", "segs": null, "full_uz": "Atrofingda Rasululloh hadisida (hadis) to'qiydiganlar va soxtalashtiradiganlarning ko'pligini ko'rib turibsan.", "note": "«الوضاعين» — hadis to'qib chiqaruvchilar, «المدلسين» — sanadni yashiruvchi/soxtalashtiruvchilar."},
  {"num": 151, "time": "00:09:55,259 --> 00:09:59,879", "arabic": "وَإِنْ لَمْ نَتَحَرَّ الدِّقَّةَ نَحْنُ طَلَبَةَ الْحَدِيثِ الشَّرِيفِ فَمَنْ يَقُومُ بِذَلِكَ؟", "segs": null, "full_uz": "Agar biz hadisi sharif talabalari aniqlikka rioya qilmasak, buni kim qiladi?", "note": null},
  {"num": 152, "time": "00:10:01,139 --> 00:10:05,879", "arabic": "صُهَيْبٌ، أَقْطَعُ، بِنِيَّةٍ صَافِيَةٍ يَا أَبَا عَبْدِ اللَّهِ وَأَنْتَ تَعْرِفُ ذَلِكَ جَيِّدًا", "segs": null, "full_uz": "Suhayb, ishonchim komilki, sof niyat bilan harakat qilgan, ey Abu Abdulloh, buni sen yaxshi bilasan.", "note": null},
  {"num": 153, "time": "00:10:06,759 --> 00:10:09,980", "arabic": "اَلنِّيَّةُ الصَّافِيَةُ لَا تُبَرِّرُ الْقَوْلَ الْخَطَأَ وَالْعَمَلَ الْكَدِرَ", "segs": null, "full_uz": "Sof niyat noto'g'ri so'z va nomukammal amalni oqlamaydi.", "note": null},
  {"num": 154, "time": "00:10:09,980 --> 00:10:13,879", "arabic": "وَالْأَهَمُّ عِنْدِي هُوَ دِقَّةُ نَقْلِ الْحَدِيثِ الشَّرِيفِ سَنَدًا وَمَتْنًا", "segs": null, "full_uz": "Mening nazdimda eng muhimi hadisi sharifni ham sanad, ham matn jihatidan aniq naql qilishdir.", "note": null},
  {"num": 155, "time": "00:10:14,720 --> 00:10:18,559", "arabic": "وَلَا مَجَالَ لِلْمُجَامَلَةِ أَوِ الْمُدَاهَنَةِ فِي عِلْمِ رَسُولِ اللَّهِ يَا أَبَا عَبْدِ الرَّحْمَنِ", "segs": null, "full_uz": "Rasululloh ilmida iltifot yoki yaltoqlanishga o'rin yo'q, ey Abu Abdurahmon.", "note": null},
  {"num": 156, "time": "00:10:18,559 --> 00:10:22,879", "arabic": "فَلْنَتْرُكْ حَدِيثَ صُهَيْبٍ كَيْ لَا أَنْسَى مَا أَتَيْتُكَ بِهِ", "segs": null, "full_uz": "Suhayb masalasini qo'yaylik, senga olib kelgan narsamni unutib qo'ymay.", "note": null},
  {"num": 157, "time": "00:10:22,879 --> 00:10:23,559", "arabic": "اِجْلِسْ", "segs": null, "full_uz": "O'tir.", "note": null},
  {"num": 158, "time": "00:10:23,559 --> 00:10:29,059", "arabic": "خَيْرًا يَا بَدْرُ", "segs": null, "full_uz": "Nima yaxshilik bo'ldi, Badr?", "note": "«خَيْرًا» — biror kishi kutilmaganda kelganda «xayriyat, nima gap?» ma'nosida so'raladigan ibora."},
  {"num": 159, "time": "00:10:29,059 --> 00:10:33,980", "arabic": "اَلْحَقُّ أَنَّنِي جِئْتُ أَعْرِضُ عَلَيْكَ شِرَاءَ دُكَّانِكَ الَّتِي فِي السُّوقِ", "segs": null, "full_uz": "Rostini aytsam, bozordagi do'koningni sotib olishni taklif qilgani keldim.", "note": null},
  {"num": 160, "time": "00:10:33,980 --> 00:10:37,080", "arabic": "وَأَنَا مُسْتَعِدٌّ لِلثَّمَنِ الَّذِي تُرِيدُهُ", "segs": null, "full_uz": "Va men sen xohlagan narxga tayyorman.", "note": null},
  {"num": 161, "time": "00:10:37,080 --> 00:10:39,980", "arabic": "دُكَّانِي؟ دُكَّانُ أَبِي؟", "segs": null, "full_uz": "Do'konimni? Otamning do'konini?", "note": null},
  {"num": 162, "time": "00:10:39,980 --> 00:10:40,379", "arabic": "أَجَلْ", "segs": null, "full_uz": "Ha.", "note": null},
  {"num": 163, "time": "00:10:40,379 --> 00:10:44,860", "arabic": "وَمَنْ زَعَمَ لَكَ أَنَّ دُكَّانِي لِلْبَيْعِ؟", "segs": null, "full_uz": "Do'konim sotuvga qo'yilgan deb senga kim aytdi?", "note": null},
  {"num": 164, "time": "00:10:44,860 --> 00:10:48,240", "arabic": "دَعْكَ مِمَّنْ زَعَمَ أَوْ مِمَّنْ قَالَ وَقُلْ لِي كَمْ تُرِيدُ ثَمَنًا لَهَا", "segs": [{"ar": "دَعْكَ مِمَّنْ زَعَمَ أَوْ مِمَّنْ قَالَ", "uz": "kim aytgani yoki kim da'vo qilganini qo'yib tur"}, {"ar": "وَقُلْ لِي كَمْ تُرِيدُ ثَمَنًا لَهَا", "uz": "faqat ayt-chi, unga qancha narx so'raysan"}], "full_uz": "Kim aytgani yoki kim da'vo qilganini qo'yib tur, faqat ayt-chi, unga qancha narx so'raysan?", "note": null},
  {"num": 165, "time": "00:10:48,240 --> 00:10:52,360", "arabic": "دُكَّانِي لَيْسَتْ لِلْبَيْعِ يَا بَدْرُ", "segs": null, "full_uz": "Do'konim sotuvga emas, Badr.", "note": null},
  {"num": 166, "time": "00:10:52,360 --> 00:10:58,439", "arabic": "وَإِنْ قُلْتُ لَكَ أَنِّي سَأَدْفَعُ لَكَ فِيهَا أَلْفَ دِرْهَمٍ", "segs": null, "full_uz": "Agar senga uning uchun ming dirham to'layman desam-chi?", "note": null},
  {"num": 167, "time": "00:10:58,439 --> 00:11:00,860", "arabic": "أَكُنْتَ تُوَافِقُ؟", "segs": null, "full_uz": "Rozi bo'larmiding?", "note": null},
  {"num": 168, "time": "00:11:05,840 --> 00:11:08,740", "arabic": "لَوْ دَفَعْتَ لِي ثَمَنَهَا مَالَ الدُّنْيَا لَنْ أَبِيعَهَا", "segs": null, "full_uz": "Dunyoning mol-mulkini to'lasang ham, uni sotmayman.", "note": null},
  {"num": 169, "time": "00:11:08,740 --> 00:11:13,440", "arabic": "سَلَامٌ عَلَيْكُمْ", "segs": null, "full_uz": "Xayr, sizga salom bo'lsin.", "note": null},
  {"num": 170, "time": "00:11:38,740 --> 00:11:58,120", "arabic": "مُنْذُ مَا جِئْتَ إِلَى هُنَا وَأَنْتَ لَمْ تَذُقْ كَثِيرًا مِنَ الطَّعَامِ", "segs": null, "full_uz": "Bu yerga kelganingdan beri deyarli ovqat yemading.", "note": null},
  {"num": 171, "time": "00:12:08,740 --> 00:12:21,899", "arabic": "مَا أَخْبَارُ وَلِيِّ الْعَهْدِ الْمَأْمُونِ؟", "segs": null, "full_uz": "Valiahd Ma'mundan qanday xabarlar bor?", "note": null},
  {"num": 172, "time": "00:12:21,899 --> 00:12:26,759", "arabic": "عَلَى الْوَجْهِ الَّذِي تُحِبُّهُ وَتَرْضَى يَا أَبَا الْفَضْلِ", "segs": null, "full_uz": "Sen yoqtiradigan va rozi bo'ladigan tarzda, ey Abul-Fazl.", "note": null},
  {"num": 173, "time": "00:12:26,759 --> 00:12:30,379", "arabic": "لَقَدِ اسْتَأْثَرْتَ بِهِ مِنْ دُونِي أَيُّهَا الْمَاكِرُ", "segs": null, "full_uz": "Sen uni mendan ustun ko'rib, o'zingga ajratib olding, ey ayyor.", "note": null},
  {"num": 174, "time": "00:12:30,379 --> 00:12:33,720", "arabic": "فَصَارَ يَمِيلُ إِلَيْكَ أَكْثَرَ مِمَّا يَمِيلُ إِلَيَّ", "segs": null, "full_uz": "Shunday qilib, u senga mendan ko'ra ko'proq moyil bo'lib qoldi.", "note": null},
  {"num": 175, "time": "00:12:33,720 --> 00:12:37,840", "arabic": "إِنْ مَالَ إِلَيَّ أَوْ مَالَ إِلَيْكَ", "segs": null, "full_uz": "U menga moyil bo'lsa ham, senga moyil bo'lsa ham.", "note": null},
  {"num": 176, "time": "00:12:37,840 --> 00:12:39,600", "arabic": "فَهُوَ حَتْمًا مَائِلٌ", "segs": null, "full_uz": "U albatta bir tomonga moyildir.", "note": null},
  {"num": 177, "time": "00:12:39,600 --> 00:12:42,060", "arabic": "مَائِلٌ إِلَى أَصْلٍ وَاحِدٍ", "segs": null, "full_uz": "Bitta asl-manbaga moyil.", "note": null},
  {"num": 178, "time": "00:12:42,060 --> 00:12:46,560", "arabic": "لَا فُضَّ فُوكَ يَا ابْنَ سَهْلٍ", "segs": null, "full_uz": "Barakalla senga, ey Ibn Sahl!", "note": "«لَا فُضَّ فُوكَ» — arabcha ibora, so'zma-so'z «og'zing sochilmasin», ya'ni «juda chiroyli aytding» ma'nosida ishlatiladi."},
  {"num": 179, "time": "00:12:46,560 --> 00:12:49,660", "arabic": "فِيكَ بَلَاغَةُ الْأَعْرَابِ وَصَنْعَةُ لُغَتِهِمْ", "segs": null, "full_uz": "Sende arablarning notiqligi va til san'ati bor.", "note": null},
  {"num": 180, "time": "00:12:49,660 --> 00:12:53,139", "arabic": "فَلْيَكُنْ لِسَانُكَ عَلَى قَلْبِكَ دَلِيلًا", "segs": null, "full_uz": "Tiling qalbingga dalil bo'lsin.", "note": null},
  {"num": 181, "time": "00:12:53,139 --> 00:12:56,840", "arabic": "وَهَلْ عِنْدَكَ شَكٌّ فِي ذَلِكَ؟", "segs": null, "full_uz": "Bunga shubhang bormi?", "note": null},
  {"num": 182, "time": "00:12:57,759 --> 00:12:59,759", "arabic": "لَوْ تَسَلَّلَتِ الشُّكُوكُ إِلَى صَدْرِي", "segs": null, "full_uz": "Agar shubhalar ko'nglimga kirib kelsa.", "note": null},
  {"num": 183, "time": "00:12:59,759 --> 00:13:02,840", "arabic": "سَتَكْتَوِي بِنِيرَانِي", "segs": null, "full_uz": "Mening olovimda kuyasan.", "note": null},
  {"num": 184, "time": "00:13:05,840 --> 00:13:07,120", "arabic": "أَعْرِفُ", "segs": null, "full_uz": "Bilaman.", "note": null},
  {"num": 185, "time": "00:13:07,120 --> 00:13:09,200", "arabic": "أَعْرِفُ يَا أَبَا الْفَضْلِ", "segs": null, "full_uz": "Bilaman, ey Abul-Fazl.", "note": null},
  {"num": 186, "time": "00:13:09,200 --> 00:13:17,460", "arabic": "إِنْ كَانَ قَدَرًا لَهَا أَنْ تَرَى أَهْلَهَا فَسَتَرَاهُمْ إِنْ شَاءَ اللَّهُ", "segs": [{"ar": "إِنْ كَانَ قَدَرًا لَهَا أَنْ تَرَى أَهْلَهَا", "uz": "agar taqdirda uning yaqinlarini ko'rishi bor bo'lsa"}, {"ar": "فَسَتَرَاهُمْ إِنْ شَاءَ اللَّهُ", "uz": "Alloh xohlasa, ularni ko'radi"}], "full_uz": "Agar taqdirda uning yaqinlarini ko'rishi bor bo'lsa, Alloh xohlasa, ko'radi.", "note": null},
  {"num": 187, "time": "00:13:17,460 --> 00:13:21,299", "arabic": "وَإِلَّا فَمَا لَكُمْ إِلَّا الْإِذْعَانُ لِقَضَاءِ اللَّهِ وَقَدَرِهِ", "segs": null, "full_uz": "Aks holda, sizlarga Allohning qazo va qadariga bo'ysunishdan boshqa chora yo'q.", "note": null},
  {"num": 188, "time": "00:13:21,299 --> 00:13:22,600", "arabic": "لَا إِلَهَ إِلَّا اللَّهُ", "segs": null, "full_uz": "Allohdan o'zga iloh yo'q.", "note": null},
  {"num": 189, "time": "00:13:22,600 --> 00:13:25,240", "arabic": "نَسِيتُ أَنْ أَسْأَلَكَ عَنْ شَيْءٍ يَا أَبَا عَبْدِ اللَّهِ", "segs": null, "full_uz": "Sendan bir narsa so'rashni unutib qo'ydim, ey Abu Abdulloh.", "note": null},
  {"num": 190, "time": "00:13:25,240 --> 00:13:27,360", "arabic": "مَا هُوَ؟", "segs": null, "full_uz": "Nima edi?", "note": null},
  {"num": 191, "time": "00:13:27,360 --> 00:13:29,200", "arabic": "لِي صَدِيقٌ مِنْ خِيَرَةِ النَّاسِ فِي بَغْدَادَ", "segs": null, "full_uz": "Bag'dodning eng yaxshi odamlaridan bo'lgan bir do'stim bor.", "note": null},
  {"num": 192, "time": "00:13:29,200 --> 00:13:32,039", "arabic": "وَقَدْ مَرَّ عَلَيَّ الْيَوْمَ يَسْأَلُنِي عَنْ دَارٍ نَكْتَرِيهَا", "segs": null, "full_uz": "Bugun oldimga kelib, ijaraga oladigan uy haqida so'radi.", "note": null},
  {"num": 193, "time": "00:13:32,039 --> 00:13:35,560", "arabic": "فَتَذَكَّرْتُ أَنَّ عَمَّكَ إِسْحَاقَ لَدَيْهِ بَيْتٌ يُؤَجَّرُ", "segs": null, "full_uz": "Shunda amaking Ishoqning ijaraga beriladigan uyi borligi esimga tushdi.", "note": null},
  {"num": 194, "time": "00:13:35,559 --> 00:13:38,179", "arabic": "أَعْتَقِدُ أَنَّهُ أَجَّرَ هَذَا الْبَيْتَ", "segs": null, "full_uz": "Menimcha, u bu uyni ijaraga bergan.", "note": null},
  {"num": 195, "time": "00:13:38,179 --> 00:13:39,799", "arabic": "خَسَارَةٌ", "segs": null, "full_uz": "Afsus.", "note": null},
  {"num": 196, "time": "00:13:39,799 --> 00:13:44,059", "arabic": "وَلَكِنْ سَمِعْتُ ابْنَ نُوحٍ يَقُولُ أَنَّ دَارَهُمْ قَدْ غَادَرَهَا مُكْتَرِيهَا", "segs": null, "full_uz": "Lekin Ibn Nuhning aytishicha, ularning uyini ijarachisi tark etgan ekan.", "note": null},
  {"num": 197, "time": "00:13:44,059 --> 00:13:46,379", "arabic": "وَهُوَ يَبْحَثُ عَنْ مُسْتَأْجِرٍ جَدِيدٍ", "segs": null, "full_uz": "Va u yangi ijarachi qidiryapti.", "note": null},
  {"num": 198, "time": "00:13:46,379 --> 00:13:49,599", "arabic": "حَقًّا؟ سَأَسْأَلُهُ لَعَلَّهُ لَمْ يُؤَجِّرْهَا بَعْدُ", "segs": null, "full_uz": "Rostdanmi? Undan so'rayman, balki hali ijaraga bermagandir.", "note": null},
  {"num": 199, "time": "00:13:49,599 --> 00:13:52,179", "arabic": "وَإِنْ رَأَيْتُهُ أَنَا قَبْلَكَ سَأُخْبِرُهُ إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Agar men uni sendan oldin ko'rsam, Alloh xohlasa, o'zim aytib qo'yaman.", "note": null},
  {"num": 200, "time": "00:13:52,179 --> 00:13:54,059", "arabic": "جَزَاكَ اللَّهُ خَيْرًا يَا أَبَا عَبْدِ اللَّهِ", "segs": null, "full_uz": "Alloh senga yaxshilik ato etsin, ey Abu Abdulloh.", "note": null},
  {"num": 201, "time": "00:13:54,059 --> 00:13:55,939", "arabic": "تَفَضَّلْ", "segs": null, "full_uz": "Marhamat, kiring.", "note": null},
  {"num": 202, "time": "00:13:58,059 --> 00:14:00,959", "arabic": "لَقَدْ رَفَضَ ابْنُ حَنْبَلٍ أَنْ يَبِيعَ دُكَّانَهُ", "segs": null, "full_uz": "Ibn Hanbal do'konini sotishni rad etdi.", "note": null},
  {"num": 203, "time": "00:14:00,959 --> 00:14:05,019", "arabic": "وَهَلْ أَخْبَرْتَهُ بِالثَّمَنِ الَّذِي سَيَأْخُذُهُ لِقَاءَهَا؟", "segs": null, "full_uz": "Buning evaziga olishi mumkin bo'lgan narxni unga aytdingmi?", "note": null},
  {"num": 204, "time": "00:14:05,019 --> 00:14:08,120", "arabic": "أَخْبَرْتُهُ لَمْ يَأْبَهْ بِهِ وَلَمْ يَهْتَمَّ", "segs": null, "full_uz": "Aytdim, u parvo qilmadi va e'tibor bermadi.", "note": null},
  {"num": 205, "time": "00:14:08,120 --> 00:14:12,279", "arabic": "وَكَيْفَ السَّبِيلُ إِلَى إِقْنَاعِ ابْنِ حَنْبَلٍ هَذَا؟", "segs": null, "full_uz": "Bu Ibn Hanbalni ko'ndirishning yo'li qanday?", "note": null},
  {"num": 206, "time": "00:14:12,279 --> 00:14:15,279", "arabic": "دَكَاكِينُ كَثِيرَةٌ وَسَنَجِدُ غَيْرَهَا لَا تَقْلَقْ", "segs": null, "full_uz": "Do'konlar ko'p, boshqasini topamiz, xavotir olma.", "note": null},
  {"num": 207, "time": "00:14:15,279 --> 00:14:20,019", "arabic": "وَلَكِنِّي لَا أُرِيدُ إِلَّا دُكَّانَ ابْنِ حَنْبَلٍ فَهِمْتَ؟", "segs": null, "full_uz": "Lekin men faqat Ibn Hanbalning do'konini xohlayman, tushundingmi?", "note": null},
  {"num": 209, "time": "00:15:05,019 --> 00:15:17,039", "arabic": "إِلَى مَتَى سَتَبْقَيْنَ عَلَى هَذِهِ الْحَالِ يَا فَوْزُ؟", "segs": null, "full_uz": "Qachongacha shu holatda qolasan, Fawz?", "note": null},
  {"num": 210, "time": "00:15:17,039 --> 00:15:22,919", "arabic": "لَا بُدَّ أَنْ أَجِدَ حَلًّا يُنْقِذُنِي مِنْ هَذَا الْجَحِيمِ الَّذِي أَتَقَلَّبُ فِيهِ", "segs": null, "full_uz": "Ichida qolib ketgan bu do'zaxdan meni qutqaradigan yechim topishim shart.", "note": null},
  {"num": 211, "time": "00:15:25,519 --> 00:15:30,699", "arabic": "لِمَاذَا لَا أَقْبَلُ بِبَيْعِي وَأَرْتَاحُ مِنْ هَذِهِ الشَّقِيَّةِ الْمَجْنُونَةِ؟", "segs": null, "full_uz": "Nega sotilishimga rozi bo'lib, bu jinni badbaxtdan qutulmayapman?", "note": null},
  {"num": 212, "time": "00:15:30,699 --> 00:15:34,539", "arabic": "مَا بِكِ يَا فَوْزُ؟", "segs": null, "full_uz": "Senga nima bo'ldi, Fawz?", "note": null},
  {"num": 213, "time": "00:15:34,539 --> 00:15:40,259", "arabic": "هَلْ جُنِنْتِ؟ كَيْفَ تَقْبَلِينَ بِأَنْ تَكُونِي جَارِيَةً؟", "segs": [{"ar": "هَلْ جُنِنْتِ؟", "uz": "aqldan ozdingmi?"}, {"ar": "كَيْفَ تَقْبَلِينَ بِأَنْ تَكُونِي جَارِيَةً؟", "uz": "cho'ri bo'lishga qanday rozi bo'lasan?"}], "full_uz": "Aqldan ozdingmi? Cho'ri bo'lishga qanday rozi bo'lasan?", "note": null},
  {"num": 214, "time": "00:15:40,259 --> 00:15:46,819", "arabic": "تَحَمَّلْتُ كُلَّ سِنِينِ الْحَبْسِ وَالْحِرْمَانِ لِأَرْضَخَ فِي النِّهَايَةِ", "segs": null, "full_uz": "Oxir-oqibat taslim bo'lish uchunmi qamoq va mahrumlikning barcha yillariga bardosh berdim?", "note": null},
  {"num": 215, "time": "00:15:46,819 --> 00:15:53,980", "arabic": "لَا، لَنْ يَكُونَ لَكِ مَا تُرِيدِينَ أَيَّتُهَا الْبَائِسَةُ زُمُرُّدُ", "segs": null, "full_uz": "Yo'q, xohlaganing bo'lmaydi, baxtsiz Zumurrud.", "note": null},
  {"num": 216, "time": "00:15:53,980 --> 00:15:55,099", "arabic": "لَا", "segs": null, "full_uz": "Yo'q.", "note": null},
  {"num": 217, "time": "00:15:55,099 --> 00:16:02,439", "arabic": "أَتَرَى يُصَدِّقُ أَبُو سَرْحَانَ فِي مَعْرِضِهِ عَلَيْهِ؟", "segs": null, "full_uz": "Sizningcha, Abu Sarhon o'z taklifida rost so'zlaydimi?", "note": null},
  {"num": 218, "time": "00:16:02,440 --> 00:16:06,180", "arabic": "وَلَكِنْ مَا حَاجَةُ أَبِي سَرْحَانَ إِلَيَّ؟", "segs": null, "full_uz": "Lekin Abu Sarhonning menga nima ehtiyoji bor?", "note": null},
  {"num": 219, "time": "00:16:06,180 --> 00:16:09,340", "arabic": "مَا يَعْنِيكَ أَنْتَ يَا فَرَجُ؟", "segs": null, "full_uz": "Senga nima farqi bor, Faraj?", "note": null},
  {"num": 220, "time": "00:16:09,340 --> 00:16:13,900", "arabic": "أَلَمْ تَكُنْ تَبْحَثُ عَنْ عَمَلٍ أَكْثَرَ مَالًا وَنَفْعًا؟", "segs": null, "full_uz": "Sen pul va foyda jihatidan ko'proq ish qidirmayapmiding?", "note": null},
  {"num": 221, "time": "00:16:13,900 --> 00:16:17,740", "arabic": "وَهُوَ يَضَعُ بَيْنَ يَدَيْكَ فُرْصَةَ عُمْرِكَ", "segs": null, "full_uz": "U esa senga umringdagi eng katta imkoniyatni taqdim etyapti.", "note": null},
  {"num": 222, "time": "00:16:17,740 --> 00:16:22,280", "arabic": "ثُمَّ إِنَّ الْأَمْرَ لَنْ يُكَلِّفَكَ كَثِيرًا", "segs": null, "full_uz": "Bundan tashqari, bu ish senga qimmatga tushmaydi.", "note": null},
  {"num": 223, "time": "00:16:22,280 --> 00:16:26,060", "arabic": "لَنْ يَحْتَاجَ مِنْكَ إِلَّا أُذُنَيْنِ صَاغِيَتَيْنِ", "segs": null, "full_uz": "Sendan faqat diqqat bilan tinglaydigan ikkita quloq talab qilinadi.", "note": null},
  {"num": 224, "time": "00:16:26,060 --> 00:16:28,780", "arabic": "لِكُلِّ كَبِيرَةٍ وَصَغِيرَةٍ فِي السُّوقِ", "segs": null, "full_uz": "Bozordagi har bir katta-kichik voqeaga.", "note": null},
  {"num": 225, "time": "00:16:28,780 --> 00:16:30,660", "arabic": "وَعَيْنَيْنِ يَقِظَتَيْنِ", "segs": null, "full_uz": "Va hushyor ikkita ko'z.", "note": null},
  {"num": 226, "time": "00:16:30,659 --> 00:16:34,379", "arabic": "أَهَذَا صِدْقٌ مَا تَعِدُنِي بِهِ يَا أَبَا سَرْحَانَ؟", "segs": null, "full_uz": "Menga va'da qilayotganing rostmi, Abu Sarhon?", "note": null},
  {"num": 227, "time": "00:16:34,379 --> 00:16:38,179", "arabic": "إِذَنْ سَأُوَدِّعُ الْفَقْرَ إِلَى غَيْرِ رَجْعَةٍ", "segs": null, "full_uz": "Unda qashshoqlik bilan abadiy xayrlashaman.", "note": null},
  {"num": 228, "time": "00:16:38,179 --> 00:16:39,779", "arabic": "وَمَنْ يَدْرِي", "segs": null, "full_uz": "Kim biladi.", "note": null},
  {"num": 229, "time": "00:16:39,779 --> 00:16:44,179", "arabic": "لَعَلِّي أَصِلُ إِلَى بَلَاطِ الْخَلِيفَةِ", "segs": null, "full_uz": "Balki xalifa saroyigacha yetib borarman.", "note": null},
  {"num": 230, "time": "00:16:44,179 --> 00:16:49,600", "arabic": "اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Sizga Allohning rahmati va salomi bo'lsin.", "note": null},
  {"num": 232, "time": "00:16:53,860 --> 00:17:00,360", "arabic": "اَللَّهُمَّ فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ", "segs": null, "full_uz": "Ey Alloh, osmonlar va yerni yaratguvchi.", "note": "Mashhur duo boshlanishi."},
  {"num": 233, "time": "00:17:00,360 --> 00:17:03,519", "arabic": "عَالِمَ الْغَيْبِ وَالشَّهَادَةِ", "segs": null, "full_uz": "G'ayb va shohidlikni Biluvchi.", "note": null},
  {"num": 234, "time": "00:17:03,519 --> 00:17:08,220", "arabic": "أَنْتَ رَبُّ كُلِّ شَيْءٍ وَمَلِيكُهُ", "segs": null, "full_uz": "Sen har narsaning Robbi va Egasisan.", "note": null},
  {"num": 235, "time": "00:17:08,220 --> 00:17:12,700", "arabic": "أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ", "segs": null, "full_uz": "Guvohlik beramanki, Allohdan o'zga iloh yo'q.", "note": null},
  {"num": 236, "time": "00:17:12,700 --> 00:17:16,620", "arabic": "وَحْدَهُ لَا شَرِيكَ لَهُ", "segs": null, "full_uz": "U yakka-yu yagona, sherigi yo'q.", "note": null},
  {"num": 237, "time": "00:17:16,620 --> 00:17:21,720", "arabic": "وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ", "segs": null, "full_uz": "Va Muhammad Uning bandasi va elchisidir.", "note": null},
  {"num": 238, "time": "00:17:21,720 --> 00:17:27,920", "arabic": "أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ", "segs": null, "full_uz": "O'zimning yomonligimdan va shaytonning yomonligi hamda uning shirkidan Senga sig'inaman.", "note": null},
  {"num": 239, "time": "00:17:30,359 --> 00:17:34,959", "arabic": "وَأَعُوذُ بِكَ أَنْ أَقْتَرِفَ سُوءًا عَلَى نَفْسِي", "segs": null, "full_uz": "Va o'zimga yomonlik qilishimdan Senga sig'inaman.", "note": null},
  {"num": 240, "time": "00:17:34,959 --> 00:17:38,099", "arabic": "أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ", "segs": null, "full_uz": "Yoki uni bir musulmonga qilib qo'yishimdan.", "note": null},
  {"num": 241, "time": "00:17:38,099 --> 00:17:44,679", "arabic": "مُنْذُ مَا جِئْتَ إِلَى هَذَا السِّجْنِ وَأَنْتَ فِي هَذِهِ الْحَالِ", "segs": null, "full_uz": "Bu zindonga kelganingdan beri shu holatdasan.", "note": null},
  {"num": 242, "time": "00:17:44,679 --> 00:17:48,279", "arabic": "مَا مَرَرْتُ بِكَ إِلَّا وَرَأَيْتُكَ تُصَلِّي أَوْ تَدْعُو اللَّهَ", "segs": null, "full_uz": "Yoningdan o'tganimda seni doim namoz o'qiyotgan yoki Allohga duo qilayotgan holda ko'rganman.", "note": null},
  {"num": 243, "time": "00:17:48,279 --> 00:17:51,859", "arabic": "مَا دُمْتَ تَحْمِلُ كُلَّ هَذَا الْإِيمَانِ فِي صَدْرِكَ", "segs": null, "full_uz": "Ko'nglingda shuncha katta iymon bo'lgan ekan.", "note": null},
  {"num": 244, "time": "00:17:51,859 --> 00:17:55,179", "arabic": "مَا الَّذِي سَاقَكَ إِلَى هُنَا؟", "segs": null, "full_uz": "Seni bu yerga nima olib keldi?", "note": null},
  {"num": 245, "time": "00:17:55,179 --> 00:17:57,179", "arabic": "لِمَاذَا خَرَجْتَ عَلَى وَلِيِّ أَمْرِ الْمُؤْمِنِينَ؟", "segs": null, "full_uz": "Nega mo'minlar hukmdoriga itoatdan chiqding?", "note": null},
  {"num": 246, "time": "00:17:57,180 --> 00:18:03,799", "arabic": "كَمْ سَنَةً مَضَتْ عَلَيْكَ وَأَنْتَ فِي هَذَا الْمَكَانِ؟", "segs": null, "full_uz": "Sen bu yerda necha yildan beri turibsan?", "note": null},
  {"num": 247, "time": "00:18:03,799 --> 00:18:10,680", "arabic": "مُنْذُ سِنِينَ حَتَّى أَنَّنِي نَسِيتُ أَنْ أَعُدَّ الْأَعْوَامَ الَّتِي أَمْضَيْتُهَا حَارِسًا فِي هَذَا السِّجْنِ", "segs": null, "full_uz": "Ko'p yillardan beri, hatto bu zindonda qorovul bo'lib o'tkazgan yillarimni sanashni ham unutib qo'ydim.", "note": null},
  {"num": 248, "time": "00:18:10,680 --> 00:18:20,680", "arabic": "وَخِلَالَ هَذِهِ الْفَتْرَةِ أَلَمْ تَعْرِفْ مِنَ الْمَسْجُونِينَ الَّذِينَ رَأَيْتَهُمْ مَنْ كَانَ مَظْلُومًا؟", "segs": null, "full_uz": "Shu davr ichida ko'rgan mahbuslaring orasida kim mazlum ekanini bilib olmadingmi?", "note": null},
  {"num": 249, "time": "00:18:20,680 --> 00:18:23,519", "arabic": "إِنْ أَرَدْتَ صِدْقًا", "segs": null, "full_uz": "Agar rost gapni xohlasang.", "note": null},
  {"num": 250, "time": "00:18:23,519 --> 00:18:26,259", "arabic": "بَيْنَ جُدْرَانِ هَذَا السِّجْنِ تَعَرَّفْتُ عَلَى الْكَثِيرِ", "segs": null, "full_uz": "Bu zindon devorlari orasida ko'plarini tanidim.", "note": null},
  {"num": 251, "time": "00:18:26,259 --> 00:18:29,680", "arabic": "مِمَّنِ اتُّهِمُوا ظُلْمًا وَسُجِنُوا عُدْوَانًا", "segs": null, "full_uz": "Zulm bilan ayblanib, dushmanlik bilan qamalganlardan.", "note": null},
  {"num": 252, "time": "00:18:31,299 --> 00:18:48,220", "arabic": "وَقَدْ أَكُونُ وَاحِدًا مِنْهُمْ", "segs": null, "full_uz": "Balki men ham ulardan biriman.", "note": null},
  {"num": 253, "time": "00:18:50,680 --> 00:18:54,799", "arabic": "فَلَيْسَ كُلُّ مَنْ قَبَعَ فِي سِجْنٍ مُذْنِبًا", "segs": null, "full_uz": "Zindonda o'tirgan har bir kishi gunohkor bo'lavermaydi.", "note": null},
  {"num": 254, "time": "00:18:54,799 --> 00:19:00,820", "arabic": "اِبْنُ يَعْقُوبَ مَثَلًا مَكَثَ فِي سِجْنِهِ سِنِينَ طَوِيلَةً", "segs": null, "full_uz": "Masalan, Yusuf (Ya'qub o'g'li) zindonida uzoq yillar qoldi.", "note": null},
  {"num": 255, "time": "00:19:00,820 --> 00:19:03,220", "arabic": "حَسَدًا وَظُلْمًا", "segs": null, "full_uz": "Hasad va zulm tufayli.", "note": null},
  {"num": 256, "time": "00:19:03,220 --> 00:19:05,279", "arabic": "فِي هَذِهِ صَدَقْتَ", "segs": null, "full_uz": "Bunda haqsan.", "note": null},
  {"num": 257, "time": "00:19:05,279 --> 00:19:09,920", "arabic": "إِنْ أَخْبَرْتُكَ عَنْ قِصَصِ الْمَظْلُومِينَ الَّذِينَ قَبَعُوا فِي هَذَا السِّجْنِ", "segs": null, "full_uz": "Agar senga bu zindonda o'tirgan mazlumlarning voqealarini aytsam.", "note": null},
  {"num": 258, "time": "00:19:09,920 --> 00:19:11,460", "arabic": "فَلَنْ تُصَدِّقَ", "segs": null, "full_uz": "Ishonmaysan.", "note": null},
  {"num": 259, "time": "00:19:11,460 --> 00:19:12,580", "arabic": "بَلْ أُصَدِّقُ", "segs": null, "full_uz": "Yo'q, ishonaman.", "note": null},
  {"num": 260, "time": "00:19:12,580 --> 00:19:15,960", "arabic": "أُصَدِّقُ فَأَنَا وَاحِدٌ مِنْهُمْ", "segs": null, "full_uz": "Ishonaman, chunki men ham ulardan biriman.", "note": null},
  {"num": 261, "time": "00:19:15,960 --> 00:19:19,400", "arabic": "وَمَعَ ذَلِكَ أُحِبُّ أَنْ أَسْمَعَ مِنْكَ", "segs": null, "full_uz": "Shunga qaramay, sendan eshitishni xohlayman.", "note": null},
  {"num": 262, "time": "00:19:19,400 --> 00:19:20,840", "arabic": "فَأَنْتَ شَاهِدُ عِيَانٍ", "segs": null, "full_uz": "Axir sen ko'z bilan ko'rgan guvohsan.", "note": null},
  {"num": 263, "time": "00:19:20,840 --> 00:19:24,519", "arabic": "هَلْ هَذَا إِذَا كَانَ لَدَيْكَ وَقْتٌ؟", "segs": null, "full_uz": "Vaqting bo'lsa shuni aytib bera olasanmi?", "note": null},
  {"num": 264, "time": "00:19:24,519 --> 00:19:26,400", "arabic": "إِنْ كَانَ لَدَيَّ وَقْتٌ", "segs": null, "full_uz": "Vaqtim bor-yo'qligiga kelsak.", "note": null},
  {"num": 265, "time": "00:19:26,400 --> 00:19:31,340", "arabic": "اَلْوَقْتُ فِي السِّجْنِ يَتَسَاوَى فِيهِ السَّجَّانُ وَالسَّجِينُ", "segs": null, "full_uz": "Zindonda vaqt jihatidan qorovul ham, mahbus ham tengdir.", "note": null},
  {"num": 266, "time": "00:19:31,340 --> 00:19:33,380", "arabic": "وَلَكِنْ", "segs": null, "full_uz": "Lekin.", "note": null},
  {"num": 267, "time": "00:19:33,380 --> 00:19:37,400", "arabic": "اَلْكُلُّ يَبْحَثُ كَيْفَ يَخْرُجُ", "segs": null, "full_uz": "Hamma qanday chiqib ketishni qidiradi.", "note": null},
  {"num": 268, "time": "00:19:37,400 --> 00:19:40,380", "arabic": "وَمَتَى تَنْتَهِي مُدَّتُهُ وَنَوْبَتُهُ", "segs": null, "full_uz": "Va muddati va navbati qachon tugashini o'ylaydi.", "note": null},
  {"num": 269, "time": "00:19:40,380 --> 00:19:44,580", "arabic": "وَلَكِنْ قَبْلَ أَنْ أَقُصَّ عَلَيْكَ الْقَصَصَ الَّتِي أَعْرِفُ", "segs": null, "full_uz": "Lekin senga bilgan voqealarimni aytib berishimdan oldin.", "note": null},
  {"num": 270, "time": "00:19:44,579 --> 00:19:51,879", "arabic": "أَلَا تُرِيدُ أَنْ تَعْرِفَ مَاذَا حَدَثَ مَعَ الَّذِينَ كَانُوا مَعَكَ فِي هَذَا السِّجْنِ؟", "segs": null, "full_uz": "Bu zindonda sen bilan birga bo'lganlarga nima bo'lganini bilishni xohlamaysanmi?", "note": null},
  {"num": 271, "time": "00:19:51,879 --> 00:19:55,019", "arabic": "كُنْتُ قَدْ طَلَبْتُ مِنْكَ سَابِقًا وَلِلْآنِ لَمْ تُخْبِرْنِي", "segs": null, "full_uz": "Ilgari sendan so'ragan edim, hozirgacha aytmading.", "note": null},
  {"num": 272, "time": "00:19:55,019 --> 00:20:00,359", "arabic": "سَمِعْتُ أَنَّ بَعْضَهُمْ قَدْ عُرِضَ عَلَى الْقَاضِي وَثَبَتَتْ تُهَمُهُمْ", "segs": null, "full_uz": "Eshitishimcha, ba'zilari qoziga taqdim etilib, ayblari isbotlangan.", "note": null},
  {"num": 273, "time": "00:20:00,359 --> 00:20:03,799", "arabic": "وَأَنْزَلَ الْخَلِيفَةُ بِهِمُ الْقِصَاصَ الَّذِي يَسْتَحِقُّونَ", "segs": null, "full_uz": "Va xalifa ularga loyiq bo'lgan jazoni bergan.", "note": null},
  {"num": 274, "time": "00:20:03,799 --> 00:20:07,599", "arabic": "وَالْآنَ بَعْدَ الَّذِي سَمِعْتَ", "segs": null, "full_uz": "Endi eshitganlaringdan keyin.", "note": null},
  {"num": 275, "time": "00:20:07,599 --> 00:20:10,599", "arabic": "أَمَا زِلْتَ تُرِيدُ سَمَاعَ قِصَصِ مَنْ ظُلِمَ؟", "segs": null, "full_uz": "Hali ham zulm ko'rganlarning voqealarini eshitishni xohlaysanmi?", "note": null},
  {"num": 276, "time": "00:20:11,779 --> 00:20:13,460", "arabic": "أَجَلْ", "segs": null, "full_uz": "Ha.", "note": null},
  {"num": 277, "time": "00:20:13,460 --> 00:20:16,920", "arabic": "أُحِبُّ أَنْ تُخْبِرَنِي بِقِصَصِهِمْ", "segs": null, "full_uz": "Ularning voqealarini menga aytib berishingni istayman.", "note": null},
  {"num": 278, "time": "00:20:16,920 --> 00:20:21,840", "arabic": "فَرُبَّمَا كَانَ لِلْمَظْلُومِ عَزَاءٌ بِمَصِيرِ مِنْهُمْ", "segs": null, "full_uz": "Balki mazlum uchun ulardan birining taqdirida taskin bo'lar.", "note": null},
  {"num": 279, "time": "00:20:21,840 --> 00:20:40,480", "arabic": "اِسْمَعْ إِذًا", "segs": null, "full_uz": "Unda eshit.", "note": null},
  {"num": 280, "time": "00:20:40,480 --> 00:20:48,839", "arabic": "اِعْلَمُوا أَيُّهَا الْإِخْوَةُ أَنَّ الْعَوَامَّ مِنَ الْمُسْلِمِينَ وَمَنْ يَتَسَيَّدُونَهُمْ", "segs": null, "full_uz": "Bilingiz, ey birodarlar, musulmonlarning omma qismi va ularga boshchilik qiluvchilar.", "note": null},
  {"num": 281, "time": "00:20:48,839 --> 00:20:53,460", "arabic": "مِمَّنْ يَدَّعُونَ أَنَّهُمْ عُلَمَاءُ أَهْلِ السُّنَّةِ وَالْجَمَاعَةِ", "segs": null, "full_uz": "O'zlarini Ahli sunna val jamoa olimlari deb da'vo qiluvchilardan.", "note": null},
  {"num": 282, "time": "00:20:53,460 --> 00:20:56,920", "arabic": "مَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ", "segs": null, "full_uz": "Allohni haqiqiy qadri bilan ulug'lamadilar.", "note": "Qur'ondagi (An'om, 91-oyat) iboraga ishora."},
  {"num": 283, "time": "00:20:56,920 --> 00:21:04,120", "arabic": "ذَلِكَ أَنَّهُمْ سَاوَوْا بَيْنَ اللَّهِ تَبَارَكَ وَتَعَالَى وَبَيْنَ مَا أَنْزَلَ مِنَ الْقُرْآنِ", "segs": null, "full_uz": "Chunki ular Alloh taboraka va taolo bilan U nozil qilgan Qur'onni tenglashtirdilar.", "note": null},
  {"num": 284, "time": "00:21:04,119 --> 00:21:13,039", "arabic": "فَأَطْبَقُوا مُجْتَمِعِينَ وَاتَّفَقُوا غَيْرَ مُتَعَارِضِينَ عَلَى أَنَّ الْقُرْآنَ قَدِيمٌ لَمْ يَخْلُقْهُ اللَّهُ", "segs": null, "full_uz": "Ular birlashib, hech qanday ixtilofsiz Qur'on qadimiy bo'lib, uni Alloh yaratmagan, degan fikrga kelishib oldilar.", "note": null},
  {"num": 285, "time": "00:21:13,039 --> 00:21:17,119", "arabic": "وَقَدْ قَالَ اللَّهُ تَعَالَى فِي كِتَابِهِ الْعَزِيزِ", "segs": null, "full_uz": "Alloh taolo O'z aziz kitobida aytgan.", "note": null},
  {"num": 286, "time": "00:21:17,119 --> 00:21:24,299", "arabic": "إِنَّا جَعَلْنَاهُ قُرْآنًا عَرَبِيًّا فَكُلُّ مَا جَعَلَهُ فَقَدْ خَلَقَهُ", "segs": null, "full_uz": "Albatta, Biz uni arabcha Qur'on qildik — U yaratgan har narsani, demak, yaratgan bo'ladi.", "note": "Birinchi jumla Qur'ondan (Zuxruf, 3-oyat) iqtibos, davomi voizning o'z sharhi."},
  {"num": 287, "time": "00:21:24,299 --> 00:21:31,799", "arabic": "وَقَالَ الْحَمْدُ لِلَّهِ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ", "segs": null, "full_uz": "Va U aytdi: «Hamd bo'lsin osmonlar va yerni yaratgan Allohga».", "note": "Qur'ondagi (An'om, 1-oyat) iqtibos."},
  {"num": 288, "time": "00:21:31,799 --> 00:21:35,359", "arabic": "وَجَعَلَ الظُّلُمَاتِ وَالنُّورَ", "segs": null, "full_uz": "Va zulmat va nurni yaratdi.", "note": null},
  {"num": 289, "time": "00:21:35,359 --> 00:21:38,819", "arabic": "وَقَالَ الَر", "segs": null, "full_uz": "Va U aytdi: «Alif-Lam-Ro».", "note": "Qur'on surasi boshlanishi (Hud, 1-oyat)."},
  {"num": 290, "time": "00:21:38,819 --> 00:21:42,639", "arabic": "كِتَابٌ أُحْكِمَتْ آيَاتُهُ", "segs": null, "full_uz": "Bu Kitobning oyatlari mukammal qilib joylashtirilgan.", "note": null},
  {"num": 291, "time": "00:21:42,639 --> 00:21:46,779", "arabic": "ثُمَّ فُصِّلَتْ مِنْ لَدُنْ حَكِيمٍ خَبِيرٍ", "segs": null, "full_uz": "So'ngra Hakim va Xabir tomonidan batafsil bayon etilgan.", "note": null},
  {"num": 292, "time": "00:21:46,779 --> 00:21:52,639", "arabic": "فَكُلُّ مُحْكَمٍ مُفَصَّلٍ دَخَلَهُ مُحْكِمٌ مُفَصِّلٌ", "segs": null, "full_uz": "Demak, mukamallashtirilgan va batafsil bayon qilingan har narsaga, uni mukamallashtiruvchi va bayon qiluvchi ta'sir ko'rsatgan.", "note": null},
  {"num": 293, "time": "00:21:52,639 --> 00:21:57,440", "arabic": "وَاللَّهُ مُحْكِمُ كِتَابِهِ وَمُفَصِّلُهُ", "segs": null, "full_uz": "Alloh esa O'z Kitobini mukamallashtiruvchi va batafsil bayon qiluvchidir.", "note": null},
  {"num": 294, "time": "00:21:57,440 --> 00:22:01,240", "arabic": "فَهُوَ خَالِقُهُ خَالِقُهُ وَمُبْدِعُهُ", "segs": null, "full_uz": "Demak, U uning Yaratuvchisi, Yaratuvchisi va Ixtiro qiluvchisidir.", "note": null},
  {"num": 295, "time": "00:22:01,240 --> 00:22:22,359", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
  {"num": 296, "time": "00:22:22,359 --> 00:22:24,240", "arabic": "عَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Va sizga ham salom va Allohning rahmati bo'lsin.", "note": null},
  {"num": 297, "time": "00:22:24,240 --> 00:22:27,359", "arabic": "أَنْتَ عَامِرٌ الْإِسْكَافِيُّ؟", "segs": null, "full_uz": "Sen Omir etikdo'zmisan?", "note": null},
  {"num": 298, "time": "00:22:27,359 --> 00:22:29,519", "arabic": "أَجَلْ أَنَا عَامِرٌ الْإِسْكَافِيُّ", "segs": null, "full_uz": "Ha, men Omir etikdo'zman.", "note": null},
  {"num": 299, "time": "00:22:29,519 --> 00:22:32,700", "arabic": "لَا بُدَّ أَنَّ سُمْعَتِي تَطِيرُ بِهَا بَغْدَادُ", "segs": null, "full_uz": "Shubhasiz, mening shuhratim Bag'dodda tarqalgan.", "note": null},
  {"num": 300, "time": "00:22:32,700 --> 00:22:35,759", "arabic": "إِذَنْ فَهَذَا دُكَّانُ أَحْمَدَ بْنِ حَنْبَلٍ", "segs": null, "full_uz": "Demak, bu Ahmad ibn Hanbalning do'koni.", "note": null},
  {"num": 301, "time": "00:22:35,759 --> 00:22:38,759", "arabic": "أَجَلْ أَجَلْ هَذَا هُوَ دُكَّانُ أَحْمَدَ بْنِ حَنْبَلٍ", "segs": null, "full_uz": "Ha, ha, bu Ahmad ibn Hanbalning do'koni.", "note": null},
  {"num": 302, "time": "00:22:38,759 --> 00:22:46,000", "arabic": "إِنَّ لِي حَدِيثًا مَعَكَ سَيَسُرُّهُ", "segs": null, "full_uz": "Men bilan bir gaplashadigan gapim bor, u xursand bo'ladi.", "note": null},
  {"num": 303, "time": "00:22:46,000 --> 00:22:49,759", "arabic": "هَذَا هُوَ الْبَيْتُ أَمَامَكَ", "segs": null, "full_uz": "Mana, oldingda turgan uy shu.", "note": null},
  {"num": 304, "time": "00:22:49,759 --> 00:22:53,579", "arabic": "تَفَحَّصْهُ جَيِّدًا وَانْظُرْ إِنْ كَانَ يَحُوزُ عَلَى رِضَاكَ", "segs": null, "full_uz": "Uni yaxshilab ko'rib chiq va ko'nglingga yoqadimi yoki yo'qligini qara.", "note": null},
  {"num": 305, "time": "00:22:53,579 --> 00:22:56,920", "arabic": "يَبْدُو لِي أَنَّ الْبَيْتَ مُنَاسِبٌ جِدًّا", "segs": null, "full_uz": "Menimcha, bu uy juda mos.", "note": null},
  {"num": 306, "time": "00:22:56,920 --> 00:22:59,500", "arabic": "كَمْ تُرِيدُ إِجْرَتَهُ يَا أَخِي؟", "segs": null, "full_uz": "Ijara haqi qancha bo'lishini xohlaysan, akajon?", "note": null},
  {"num": 307, "time": "00:22:59,500 --> 00:23:02,960", "arabic": "مَا دُمْتَ قَدْ جِئْتَ مِنْ قِبَلِ أَخِي مَرْوَانَ فَلَنْ أَخْتَلِفَ", "segs": null, "full_uz": "Aka Marvon tomonidan kelgan ekansan, kelishmovchilikka bormayman.", "note": null},
  {"num": 308, "time": "00:23:02,960 --> 00:23:04,079", "arabic": "بَارَكَ اللَّهُ فِيكَ", "segs": null, "full_uz": "Alloh senga barakot bersin.", "note": null},
  {"num": 309, "time": "00:23:04,079 --> 00:23:06,480", "arabic": "اَلْمُهِمُّ أَنَّهُ حَازَ عَلَى رِضَاكَ", "segs": null, "full_uz": "Muhimi, u sening rozilikingga sazovor bo'ldi.", "note": null},
  {"num": 310, "time": "00:23:06,480 --> 00:23:11,619", "arabic": "أَرْضَانِي أَكْثَرُ أَنْ أَتَعَرَّفَ إِلَى شَابٍّ رَائِعٍ مِثْلِكَ", "segs": null, "full_uz": "Meni sen kabi ajoyib yigit bilan tanishganim yanada xursand qildi.", "note": null},
  {"num": 311, "time": "00:23:11,619 --> 00:23:13,819", "arabic": "بَارَكَ اللَّهُ فِيكَ يَا ابْنَ أَبِي دُوَادٍ", "segs": null, "full_uz": "Alloh senga barakot bersin, ey Ibn Abi Duod.", "note": null},
  {"num": 312, "time": "00:23:13,819 --> 00:23:15,339", "arabic": "تَفَضَّلْ", "segs": null, "full_uz": "Marhamat.", "note": null},
  {"num": 313, "time": "00:23:15,339 --> 00:23:19,660", "arabic": "سَأَلْتَنِي مَنِ الَّذِي يَنَالُ إِعْجَابَكَ مِنَ الشُّعَرَاءِ يَا مَوْلَايَ", "segs": null, "full_uz": "Shoirlardan kim seni hayratga soladi, deb so'radingiz, xo'jayinim.", "note": null},
  {"num": 314, "time": "00:23:19,660 --> 00:23:23,039", "arabic": "وَأَنْتَ تَدْرِي هَوَايَ فِي بَشَّارِ بْنِ بُرْدٍ", "segs": null, "full_uz": "Bashshor ibn Burdga bo'lgan moyilligimni bilasiz.", "note": null},
  {"num": 315, "time": "00:23:23,039 --> 00:23:26,960", "arabic": "وَبِمَ اسْتَأْثَرَكَ بَشَّارُ بْنُ بُرْدٍ؟", "segs": null, "full_uz": "Bashshor ibn Burd sizni nima bilan o'ziga tortdi?", "note": null},
  {"num": 316, "time": "00:23:26,960 --> 00:23:29,160", "arabic": "رُبَّمَا بِجُرْأَتِهِ وَجَسَارَتِهِ", "segs": null, "full_uz": "Balki uning jasorati va dadilligi bilan.", "note": null},
  {"num": 317, "time": "00:23:29,160 --> 00:23:31,779", "arabic": "اِبْنُ بُرْدٍ جَرِيءٌ؟", "segs": null, "full_uz": "Ibn Burd jasurmi?", "note": null},
  {"num": 318, "time": "00:23:31,779 --> 00:23:33,900", "arabic": "أَقْصِدُ فِي شِعْرِهِ يَا مَوْلَايَ", "segs": null, "full_uz": "She'rida deganim edi, xo'jayinim.", "note": null},
  {"num": 319, "time": "00:23:33,900 --> 00:23:37,560", "arabic": "وَأَيْنَ وَجَدْتَ جُرْأَتَهُ يَا ابْنَ الرَّبِيعِ؟", "segs": null, "full_uz": "Uning jasoratini qayerda topding, ey Ibn Rabi?", "note": null},
  {"num": 320, "time": "00:23:37,560 --> 00:23:40,360", "arabic": "أَلَمْ يُجَاهِرْ ابْنُ بُرْدٍ بِالنَّيْلِ مِنْ أُمَّةِ الْعَرَبِ؟", "segs": null, "full_uz": "Ibn Burd arab millatiga oshkora hujum qilmaganmidi?", "note": null},
  {"num": 321, "time": "00:23:40,360 --> 00:23:43,600", "arabic": "بَلْ وَصَلَتْ جُرْأَتُهُ إِلَى النَّيْلِ مِنَ الْإِسْلَامِ أَيْضًا", "segs": null, "full_uz": "Balki uning jasorati islomga hujum qilishgacha yetdi.", "note": null},
  {"num": 322, "time": "00:23:43,600 --> 00:23:46,200", "arabic": "لِأَنَّهُ فِي ظَنِّهِ دِينُ الْعَرَبِ فَحَسْبُ", "segs": null, "full_uz": "Chunki uning fikricha, u faqat arablarning dini.", "note": null},
  {"num": 323, "time": "00:23:46,200 --> 00:23:49,120", "arabic": "هَذَا كَلَامُ حَاقِدٍ لَا كَلَامُ نَاقِدٍ", "segs": null, "full_uz": "Bu kinachining gapi, tanqidchining gapi emas.", "note": null},
  {"num": 324, "time": "00:23:49,120 --> 00:23:52,400", "arabic": "أَنَسِيتَ يَا جَعْفَرُ أَنَّ مَوْلَايَ الْمَهْدِيَّ رَحِمَهُ اللَّهُ", "segs": null, "full_uz": "Unutdingmi, Ja'far, xo'jayinim Mahdiy — Alloh unga rahmat qilsin —", "note": null},
  {"num": 325, "time": "00:23:52,400 --> 00:23:54,200", "arabic": "جَلَدَهُ بِتُهْمَةِ الزَّنْدَقَةِ؟", "segs": null, "full_uz": "uni zandaqa (dinsizlik) ayblovi bilan qamchilaganini?", "note": null},
  {"num": 326, "time": "00:23:54,880 --> 00:23:56,640", "arabic": "مَا لَنَا وَهَذَا؟", "segs": null, "full_uz": "Bunga bizning nima aloqamiz bor?", "note": null},
  {"num": 327, "time": "00:23:56,640 --> 00:23:57,800", "arabic": "نَحْنُ نَخُوضُ فِي الشِّعْرِ", "segs": null, "full_uz": "Biz she'r haqida gaplashyapmiz.", "note": null},
  {"num": 328, "time": "00:23:57,800 --> 00:23:59,540", "arabic": "لَا فِي الدِّينِ وَالِاعْتِقَادِ", "segs": null, "full_uz": "Din va e'tiqod haqida emas.", "note": null},
  {"num": 329, "time": "00:23:59,540 --> 00:24:01,240", "arabic": "لَا أَرَى فَرْقًا بَيْنَهُمَا", "segs": null, "full_uz": "Men ular orasida farq ko'rmayapman.", "note": null},
  {"num": 330, "time": "00:24:01,240 --> 00:24:04,460", "arabic": "فَالشِّعْرُ صَدَى الْعَقْلِ وَمِرْآةُ الْقَلْبِ", "segs": null, "full_uz": "Chunki she'r — aqlning aks-sadosi va qalbning oynasidir.", "note": null},
  {"num": 331, "time": "00:24:04,460 --> 00:24:06,800", "arabic": "أَمْ أَنَّكَ تُمَجِّدُهُ وَتُفَاخِرُ بِهِ", "segs": null, "full_uz": "Yoki uni ulug'lab, u bilan faxrlanyapsanmi?", "note": null},
  {"num": 332, "time": "00:24:06,800 --> 00:24:10,840", "arabic": "لِوَازِعٍ آخَرَ غَيْرِ الْبَلَاغَةِ وَالْفَصَاحَةِ؟", "segs": null, "full_uz": "Balog'at va fasohatdan boshqa bir sabab bilanmi?", "note": null},
  {"num": 333, "time": "00:24:10,840 --> 00:24:12,860", "arabic": "مَاذَا تَقْصِدُ يَا ابْنَ الرَّبِيعِ؟", "segs": null, "full_uz": "Nimani nazarda tutyapsan, Ibn Rabi?", "note": null},
  {"num": 334, "time": "00:24:12,860 --> 00:24:15,680", "arabic": "فِي كَلَامِكَ غَمْزٌ وَلَمْزٌ لَا أَرْضَى بِهِمَا", "segs": null, "full_uz": "Gapingda men rozi bo'lmaydigan kesatiq va ta'na bor.", "note": null},
  {"num": 335, "time": "00:24:15,680 --> 00:24:18,540", "arabic": "لَوْ لَمْ نَكُنْ فِي حَضْرَةِ أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Agar mo'minlar amiri huzurida bo'lmaganimizda.", "note": null},
  {"num": 336, "time": "00:24:18,540 --> 00:24:20,460", "arabic": "لَكَانَ لِي مَعَكَ شَأْنٌ آخَرُ", "segs": null, "full_uz": "Sen bilan boshqacha gaplashardim.", "note": null},
  {"num": 337, "time": "00:24:20,460 --> 00:24:21,380", "arabic": "جَعْفَرُ", "segs": null, "full_uz": "Ja'far!", "note": null},
  {"num": 338, "time": "00:24:21,380 --> 00:24:23,500", "arabic": "مَوْلَايَ", "segs": null, "full_uz": "Xo'jayinim.", "note": null},
  {"num": 339, "time": "00:24:26,640 --> 00:24:33,640", "arabic": "إِنَّمَا أَرَدْتُ أَنْ أَسْمَعَ بَعْضًا مِنَ الشِّعْرِ", "segs": null, "full_uz": "Men faqat she'rdan bir qismini eshitmoqchi edim.", "note": null},
  {"num": 340, "time": "00:24:33,640 --> 00:24:37,360", "arabic": "لَا مُهَاتَرَاتٍ صِبْيَانِيَّةً يَا ابْنَ الرَّبِيعِ", "segs": null, "full_uz": "Bolalarcha janjal emas, Ibn Rabi.", "note": null},
  {"num": 341, "time": "00:24:43,600 --> 00:24:46,780", "arabic": "قَدْ عَرَضَ عَلَيَّ الرَّجُلُ خَمْسِينَ دِرْهَمًا", "segs": null, "full_uz": "U kishi menga ellik dirham taklif qildi.", "note": null},
  {"num": 342, "time": "00:24:46,780 --> 00:24:49,820", "arabic": "إِنْ أَنَا أَقْنَعْتُ أَحْمَدَ بْنَ حَنْبَلٍ بِبَيْعِ الدُّكَّانِ", "segs": null, "full_uz": "Agar men Ahmad ibn Hanbalni do'konni sotishga ko'ndira olsam.", "note": null},
  {"num": 343, "time": "00:24:49,820 --> 00:24:51,400", "arabic": "خَمْسِينَ دِرْهَمًا؟", "segs": null, "full_uz": "Ellik dirhamni?", "note": null},
  {"num": 344, "time": "00:24:51,400 --> 00:24:54,020", "arabic": "أَجَلْ يَا سَلَمَةُ خَمْسِينَ دِرْهَمًا", "segs": null, "full_uz": "Ha, Salama, ellik dirham.", "note": null},
  {"num": 345, "time": "00:24:54,019 --> 00:24:58,839", "arabic": "وَوَعَدَنِي أَنْ يُخَفِّضَ إِجْرَةَ الدُّكَّانِ إِلَى النِّصْفِ إِنْ أَنَا أَقْنَعْتُهُ", "segs": null, "full_uz": "Agar men uni ko'ndirsam, do'kon ijarasini yarmiga tushirishga va'da berdi.", "note": null},
  {"num": 346, "time": "00:25:02,220 --> 00:25:06,240", "arabic": "آهِ يَا سَلَمَةُ كَمْ هُوَ رَجُلٌ كَرِيمٌ", "segs": null, "full_uz": "Oh, Salama, u qanchalik saxovatli odam!", "note": null},
  {"num": 347, "time": "00:25:02,220 --> 00:25:06,240", "arabic": "تُرَى أَسَيَقْبَلُ أَحْمَدُ بِبَيْعِ الدُّكَّانِ؟", "segs": null, "full_uz": "Qiziq, Ahmad do'konni sotishga rozi bo'larmikan?", "note": null},
  {"num": 348, "time": "00:25:06,240 --> 00:25:07,660", "arabic": "وَلِمَ يَرْفُضُ؟", "segs": null, "full_uz": "Nega rad etar ekan?", "note": null},
  {"num": 349, "time": "00:25:07,660 --> 00:25:11,619", "arabic": "اِبْنُ حَنْبَلٍ أَعْقَلُ مِنْكَ أَنْتَ وَصَاحِبِكَ هَذَا", "segs": null, "full_uz": "Ibn Hanbal sendan va bu do'stingdan ancha aqllidir.", "note": null},
  {"num": 350, "time": "00:25:11,619 --> 00:25:14,400", "arabic": "وَلَا أَظُنُّهُ سَيُفَرِّطُ فِي دُكَّانِ أَبِيهِ", "segs": null, "full_uz": "Va u otasining do'konidan voz kechadi deb o'ylamayman.", "note": null},
  {"num": 351, "time": "00:25:14,400 --> 00:25:16,960", "arabic": "إِنَّهَا مَصْدَرُ دَخْلٍ ثَابِتٍ وَجَارٍ", "segs": null, "full_uz": "U doimiy va uzluksiz daromad manbaidir.", "note": null},
  {"num": 352, "time": "00:25:16,960 --> 00:25:22,139", "arabic": "وَالنُّقُودُ كَالطُّيُورِ يَا وَلَدِي كُلَّ يَوْمٍ هِيَ عَلَى غُصْنٍ", "segs": null, "full_uz": "Pul qushlarga o'xshaydi, o'g'lim, har kuni boshqa shoxda o'tiradi.", "note": null},
  {"num": 353, "time": "00:25:22,139 --> 00:25:23,839", "arabic": "اِطْرَحْ عَنْكَ هَذِهِ الْأَوْهَامَ", "segs": null, "full_uz": "Bu xayollarni tashla.", "note": null},
  {"num": 354, "time": "00:25:23,839 --> 00:25:30,159", "arabic": "مَا بِكَ؟", "segs": null, "full_uz": "Senga nima bo'ldi?", "note": null},
  {"num": 355, "time": "00:25:30,159 --> 00:25:34,259", "arabic": "أُمِّي نَسِيتُ أَنْ أُعْطِيَ أَحْمَدَ بْنَ حَنْبَلٍ كِرَاءَةَ دُكَّانٍ", "segs": null, "full_uz": "Onajon, Ahmad ibn Hanbalga do'kon ijarasini berishni unutib qo'ydim.", "note": null},
  {"num": 356, "time": "00:25:34,259 --> 00:25:36,539", "arabic": "إِنَّهُ يَغُضُّ الطَّرْفَ عَنِّي مُنْذُ أَشْهُرٍ يَا أُمِّي", "segs": null, "full_uz": "U necha oydan beri menga ko'z yumib kelyapti, onajon.", "note": null},
  {"num": 357, "time": "00:25:36,539 --> 00:25:37,899", "arabic": "لَا بُدَّ أَنَّهُ بِحَاجَتِهَا", "segs": null, "full_uz": "Shubhasiz, unga muhtoj.", "note": null},
  {"num": 358, "time": "00:25:37,899 --> 00:25:40,359", "arabic": "إِذَنِ اذْهَبْ إِلَيْهِ غَدًا وَأَعْطِهِ مَالَهُ", "segs": null, "full_uz": "Unda ertaga uning oldiga bor va pulini ber.", "note": null},
  {"num": 359, "time": "00:25:40,359 --> 00:25:42,899", "arabic": "ثُمَّ فَاتِحْهُ فِي أَمْرِ بَيْعِ دُكَّانِهِ", "segs": null, "full_uz": "So'ngra do'konini sotish masalasini ochib gaplash.", "note": null},
  {"num": 360, "time": "00:25:42,899 --> 00:25:45,859", "arabic": "أَحْسَنَ أَحْسَنَ يَا سَلَمَةُ", "segs": null, "full_uz": "Barakalla, barakalla, Salama.", "note": null},
  {"num": 361, "time": "00:25:45,859 --> 00:25:49,859", "arabic": "أُمِّي أَقْصِدُ كَيْ يَبْدُوَ الْأَمْرُ طَبِيعِيًّا", "segs": null, "full_uz": "Onajon, ish tabiiy ko'rinishi uchun demoqchiman.", "note": null},
  {"num": 362, "time": "00:25:49,859 --> 00:25:51,240", "arabic": "أَنَا أَرَى غَيْرَ ذَلِكَ", "segs": null, "full_uz": "Men boshqacha fikrdaman.", "note": null},
  {"num": 363, "time": "00:25:51,240 --> 00:25:54,460", "arabic": "إِنْ كُنْتَ سَتُفَاتِحُهُ بِبَيْعِ الدُّكَّانِ", "segs": null, "full_uz": "Agar unga do'kon sotish haqida gap ochsang.", "note": null},
  {"num": 364, "time": "00:25:54,460 --> 00:25:57,440", "arabic": "أَرَى أَنْ تُؤَخِّرَ الْأُجْرَةَ لِبَعْضِ الْوَقْتِ", "segs": null, "full_uz": "Menimcha, ijarani bir muddat kechiktirgan ma'qul.", "note": null},
  {"num": 365, "time": "00:25:57,440 --> 00:25:59,660", "arabic": "أُؤَخِّرُ دَفْعَ الْأُجْرَةِ لِبَعْضِ الْوَقْتِ؟", "segs": null, "full_uz": "Ijara to'lovini bir muddat kechiktiraymi?", "note": null},
  {"num": 366, "time": "00:25:59,660 --> 00:26:03,339", "arabic": "هَكَذَا نُقَابِلُ صَبْرَ الرَّجُلِ بِاللُّؤْمِ وَالْخَبْطِ يَا أُمِّي؟", "segs": null, "full_uz": "Bu odamning sabriga pastkashlik va tartibsizlik bilan javob qaytaramizmi, onajon?", "note": null},
  {"num": 367, "time": "00:26:03,339 --> 00:26:06,779", "arabic": "لَا يَجُوزُ عَيْبٌ هَذَا لَيْسَ مِنْ أَخْلَاقِ الرِّجَالِ يَا أُمِّي", "segs": null, "full_uz": "Bu mumkin emas, ayb, bu erkaklar axloqidan emas, onajon.", "note": null},
  {"num": 368, "time": "00:26:06,779 --> 00:26:08,740", "arabic": "تَذَكَّرِي مَا قُلْتِ لِي تَذَكَّرِي", "segs": null, "full_uz": "Menga aytganingni eslab ko'r, eslab ko'r.", "note": null},
  {"num": 369, "time": "00:26:08,740 --> 00:26:11,200", "arabic": "إِنَّ الدُّكَّانَ مَوْرِدُ رِزْقِهِمُ الْوَحِيدُ", "segs": null, "full_uz": "Do'kon ularning yagona rizq manbai.", "note": null},
  {"num": 370, "time": "00:26:11,200 --> 00:26:15,000", "arabic": "وَهَذَا هُوَ بَيْتُ الْقَصِيدِ وَغَايَةُ مَا نُرِيدُ", "segs": null, "full_uz": "Va aynan shu bizning maqsadimiz va istagan narsamiz.", "note": "«بيت القصيد» — masalaning eng muhim, asosiy nuqtasi ma'nosidagi ibora."},
  {"num": 371, "time": "00:26:15,000 --> 00:26:17,740", "arabic": "قَصِيدٌ نُرِيدُ؟ أُمِّي تَقُولُ الشِّعْرَ يَا سَلَمَةُ", "segs": null, "full_uz": "Qasida istaymizmi? Onam she'r aytyapti-ya, Salama.", "note": null},
  {"num": 372, "time": "00:26:17,740 --> 00:26:19,240", "arabic": "كَيْفَ كَيْفَ يَا أُمِّي؟", "segs": null, "full_uz": "Qanday, qanday, onajon?", "note": null},
  {"num": 373, "time": "00:26:21,240 --> 00:26:31,839", "arabic": "لِمَ لَمْ تُجَهِّزِي نَفْسَكِ يَا أَيَّتُهَا الْفَتَاةُ الْبَائِسَةُ؟", "segs": null, "full_uz": "Nega o'zingni tayyorlamading, baxtsiz qiz?", "note": null},
  {"num": 374, "time": "00:26:31,839 --> 00:26:36,079", "arabic": "أَلَمْ أَقُلْ لَكِ إِنَّ هُنَاكَ رَجُلًا مِنْ مَلَأِ بَغْدَادَ سَيَأْتِي لِيَرَاكِ؟", "segs": null, "full_uz": "Senga Bag'dodning zodagonlaridan bir kishi seni ko'rgani kelishini aytmaganmidim?", "note": null},
  {"num": 375, "time": "00:26:36,079 --> 00:26:38,519", "arabic": "وَإِنْ أَعْجَبَتْهُ سَيَشْتَرِيكِ", "segs": null, "full_uz": "Agar sen unga yoqsang, seni sotib oladi.", "note": null},
  {"num": 376, "time": "00:26:38,519 --> 00:26:42,339", "arabic": "أَنْتِ قُلْتِ مَا عِنْدَكِ وَأَنَا لَمْ أَقُلْ شَيْئًا", "segs": null, "full_uz": "Sen aytganingni ayting, men esa hech narsa demadim.", "note": null},
  {"num": 377, "time": "00:26:42,339 --> 00:26:46,240", "arabic": "أَيَّتُهَا الْمَجْنُونَةُ فِي دَارِهِ سَتَعِيشِينَ كَالْأَمِيرَاتِ", "segs": null, "full_uz": "Ey jinni, uning uyida malikalardek yashaysan.", "note": null},
  {"num": 378, "time": "00:26:46,240 --> 00:26:49,240", "arabic": "أَفْضَلُ مِنْ أَنْ تَبْقَيْ فِي هَذِهِ الدَّارِ الْبَائِسَةِ", "segs": null, "full_uz": "Bu baxtsiz uyda qolganingdan ko'ra yaxshi.", "note": null},
  {"num": 379, "time": "00:26:49,240 --> 00:26:51,859", "arabic": "أَرْتَاحُ مِنْكِ وَتَرْتَاحِينَ مِنِّي", "segs": null, "full_uz": "Men sendan, sen esa mendan qutulasan.", "note": null},
  {"num": 380, "time": "00:26:51,859 --> 00:26:54,019", "arabic": "قُلْتِ حَقًّا", "segs": null, "full_uz": "Rost aytding.", "note": null},
  {"num": 381, "time": "00:26:54,019 --> 00:26:56,200", "arabic": "لَنْ أُبَاعَ لَهُ وَلَا لِغَيْرِهِ", "segs": null, "full_uz": "Men na unga, na boshqasiga sotilaman.", "note": null},
  {"num": 382, "time": "00:26:56,200 --> 00:26:57,759", "arabic": "حَتَّى لَوْ كَانَ أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Hatto u mo'minlar amiri bo'lsa ham.", "note": null},
  {"num": 383, "time": "00:26:57,759 --> 00:26:58,799", "arabic": "أَنَا حُرَّةٌ", "segs": null, "full_uz": "Men ozodman.", "note": null},
  {"num": 385, "time": "00:27:00,759 --> 00:27:02,839", "arabic": "هَلْ سَمِعْتَنِي أَيُّهَا السَّيِّدُ؟", "segs": null, "full_uz": "Meni eshitdingizmi, hazratim?", "note": null},
  {"num": 386, "time": "00:27:02,839 --> 00:27:03,299", "arabic": "اُخْرُسِي", "segs": null, "full_uz": "Jim bo'l!", "note": null},
  {"num": 389, "time": "00:27:07,299 --> 00:27:09,660", "arabic": "أُقْسِمُ إِنْ بَقِيتِ عَلَى هَذَا الْحَالِ", "segs": null, "full_uz": "Qasam ichamanki, shu holingda qolsang.", "note": null},
  {"num": 390, "time": "00:27:09,660 --> 00:27:11,839", "arabic": "لَأَقْتُلَنَّكِ وَأَرْتَاحَ مِنْكِ", "segs": null, "full_uz": "Seni albatta o'ldiraman va sendan qutulaman.", "note": null},
  {"num": 391, "time": "00:27:11,839 --> 00:27:14,240", "arabic": "مَا بِهَذِهِ الْفَتَاةِ", "segs": null, "full_uz": "Bu qizga nima bo'ldi?", "note": null},
  {"num": 392, "time": "00:27:14,240 --> 00:27:16,620", "arabic": "لِمَاذَا تُعَامِلُونَهَا بِهَذِهِ الْقَسْوَةِ", "segs": null, "full_uz": "Nega unga bunchalik qattiqqo'llik bilan munosabatda bo'lyapsizlar?", "note": null},
  {"num": 393, "time": "00:27:19,240 --> 00:27:32,680", "arabic": "هِيَ مَنْ يُجْبِرُنَا عَلَى هَذِهِ الْمُعَامَلَةِ", "segs": null, "full_uz": "Bizni shunday munosabatda bo'lishga majbur qilayotgan aynan o'zi.", "note": null},
  {"num": 394, "time": "00:27:32,680 --> 00:27:34,299", "arabic": "بَعْدَ أَنِ اشْتَرَيْنَاهَا", "segs": null, "full_uz": "Uni sotib olganimizdan keyin.", "note": null},
  {"num": 395, "time": "00:27:34,299 --> 00:27:36,880", "arabic": "اِكْتَشَفْنَا أَنَّهَا تُصَابُ بِحَالٍ مِنَ الْجُنُونِ", "segs": null, "full_uz": "Unda jinnilik holati borligini bilib qoldik.", "note": null},
  {"num": 396, "time": "00:27:36,880 --> 00:27:39,839", "arabic": "وَلَكِنْ هَذَا الْحَالُ لَا يَسْتَمِرُّ إِلَّا لَحَظَاتٍ", "segs": null, "full_uz": "Lekin bu holat faqat bir necha lahza davom etadi.", "note": null},
  {"num": 397, "time": "00:27:39,839 --> 00:27:41,799", "arabic": "وَبَعْدَهَا تَعُودُ كَمَا كَانَتْ", "segs": null, "full_uz": "Va undan keyin avvalgidek bo'lib qoladi.", "note": null},
  {"num": 398, "time": "00:27:43,799 --> 00:27:45,339", "arabic": "إِنَّهَا كَذِبَةٌ", "segs": null, "full_uz": "Bu yolg'on.", "note": null},
  {"num": 399, "time": "00:27:45,339 --> 00:27:46,839", "arabic": "أَنَا حُرَّةٌ", "segs": null, "full_uz": "Men ozodman.", "note": null},
  {"num": 400, "time": "00:27:46,839 --> 00:27:49,539", "arabic": "وَسَأَبْقَى كَذَلِكَ مَا حَيِيتُ", "segs": null, "full_uz": "Va tirik ekanman shunday qolaman.", "note": null},
  {"num": 401, "time": "00:27:49,539 --> 00:27:52,559", "arabic": "هِيَ مَنْ سَلَّمَنِي حُرِّيَّتِي", "segs": null, "full_uz": "Ozodligimni menga topshirgan aynan o'zi.", "note": null},
  {"num": 402, "time": "00:27:52,559 --> 00:27:55,879", "arabic": "وَتُرِيدُ أَنْ تَبِيعَنِي لِتَكْسِبَ مَالًا", "segs": null, "full_uz": "Va endi pul topish uchun meni sotmoqchi.", "note": null},
  {"num": 403, "time": "00:27:55,879 --> 00:27:57,699", "arabic": "لَا كَذِبَةٌ", "segs": null, "full_uz": "Yo'q, yolg'on.", "note": null},
  {"num": 404, "time": "00:27:57,699 --> 00:27:59,839", "arabic": "كَذِبَةٌ", "segs": null, "full_uz": "Yolg'on.", "note": null},
  {"num": 405, "time": "00:27:59,839 --> 00:28:03,879", "arabic": "أَلَمْ أَقُلْ لَكَ إِنَّهَا مَجْنُونَةٌ؟", "segs": null, "full_uz": "Senga u jinni deb aytmaganmidim?", "note": null},
  {"num": 406, "time": "00:28:03,879 --> 00:28:06,259", "arabic": "هَذَا الصَّكُّ الَّذِي يُثْبِتُ مِلْكِيَّتَنَا لَهَا", "segs": null, "full_uz": "Mana, unga egaligimizni tasdiqlovchi hujjat.", "note": null},
  {"num": 407, "time": "00:28:06,259 --> 00:28:09,859", "arabic": "مَعَ أَنَّ هَذَا الْحَالَ لَا يُصِيبُهَا إِلَّا نَادِرًا", "segs": null, "full_uz": "Holbuki, bu holat unga faqat kamdan-kam bo'ladi.", "note": null},
  {"num": 408, "time": "00:28:09,859 --> 00:28:13,679", "arabic": "وَلَكِنْ شَاءَ اللَّهُ أَنْ يُصِيبَهَا الْيَوْمَ أَثْنَاءَ وُجُودِكَ", "segs": null, "full_uz": "Lekin Alloh xohladiki, aynan siz bo'lganingizda bo'ldi.", "note": null},
  {"num": 409, "time": "00:28:13,680 --> 00:28:27,660", "arabic": "حَسَنًا", "segs": null, "full_uz": "Xo'p bo'ladi.", "note": null},
  {"num": 410, "time": "00:28:27,660 --> 00:28:30,460", "arabic": "سَأَذْهَبُ الْآنَ وَأَعُودُ لَاحِقًا", "segs": null, "full_uz": "Hozir ketaman va keyinroq qaytaman.", "note": null},
  {"num": 411, "time": "00:28:30,460 --> 00:28:33,160", "arabic": "رُبَّمَا تَكُونُ قَدِ اسْتَعَادَتْ عَقْلَهَا", "segs": null, "full_uz": "Balki o'shanda aqli o'ziga qaytgan bo'lar.", "note": null},
  {"num": 412, "time": "00:28:33,160 --> 00:28:36,039", "arabic": "عَلَى الرَّحْبِ وَالسَّعَةِ فِي الْوَقْتِ الَّذِي تَشَاءُ", "segs": null, "full_uz": "Xohlagan vaqtingizda marhamat, xush kelibsiz.", "note": null},
  {"num": 415, "time": "00:29:43,680 --> 00:30:08,100", "arabic": "إِذَا جَاءَ يَوْمٌ صَالِحٌ فَاقْبَلْ لَهُ", "segs": null, "full_uz": "Yaxshi kun kelsa, uni qabul qil.", "note": null},
  {"num": 416, "time": "00:30:08,100 --> 00:30:11,360", "arabic": "فَأَنْتَ عَلَى يَوْمِ الشَّقَاءِ قَدِيرٌ", "segs": null, "full_uz": "Sen baxtsizlik kuniga ham bardosh bera olasan.", "note": null},
  {"num": 418, "time": "00:30:39,680 --> 00:30:42,680", "arabic": "لَا مِنْ شَيْءٍ يُحْزِنُنَا أَوْ يُكَدِّرُنَا", "segs": null, "full_uz": "Bizni g'amgin qiladigan yoki xafa qiladigan hech narsa yo'q.", "note": null},
  {"num": 419, "time": "00:30:43,680 --> 00:30:46,680", "arabic": "إِلَّا أَنْ نَغْفُلَ عَنْ ذِكْرِ اللَّهِ عَزَّ وَجَلَّ", "segs": null, "full_uz": "Faqat Allohni zikr qilishdan g'ofil bo'lib qolishimizdan tashqari.", "note": null},
  {"num": 420, "time": "00:30:49,680 --> 00:30:53,680", "arabic": "أَمِيرُ الْمُؤْمِنِينَ يَطْلُبُكُمْ لِلْمُثُولِ أَمَامَهُ", "segs": null, "full_uz": "Mo'minlar amiri sizlarni o'z huzuriga chaqiryapti.", "note": null},
  {"num": 421, "time": "00:30:54,680 --> 00:30:57,680", "arabic": "اَلسَّمْعُ وَالطَّاعَةُ لِأَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Eshitish va bo'ysunish mo'minlar amiriga bo'lsin.", "note": null},
  {"num": 422, "time": "00:31:01,680 --> 00:31:06,680", "arabic": "هَلْ تَعْرِفُ مَا الَّذِي يَنْتَظِرُكَ عِنْدَ أَمِيرِ الْمُؤْمِنِينَ؟", "segs": null, "full_uz": "Mo'minlar amiri huzurida seni nima kutayotganini bilasanmi?", "note": null},
  {"num": 423, "time": "00:31:06,680 --> 00:31:11,799", "arabic": "يَنْتَظِرُنَا قَضَاءُ اللَّهِ وَقَدَرُهُ", "segs": null, "full_uz": "Bizni Allohning qazo va qadari kutmoqda.", "note": null},
  {"num": 424, "time": "00:31:11,799 --> 00:31:19,600", "arabic": "هَيِّئْ نَفْسَكَ لِلْمَوْتِ إِذَنْ", "segs": null, "full_uz": "Unda o'limga tayyorlan.", "note": null},
  {"num": 425, "time": "00:31:19,600 --> 00:31:23,279", "arabic": "قُلْ لَنْ يُصِيبَنَا إِلَّا مَا كَتَبَ اللَّهُ لَنَا", "segs": null, "full_uz": "Ayt: bizga faqat Alloh yozgan narsa yetadi.", "note": "Qur'ondagi (Tavba, 51-oyat) ma'nosiga yaqin ibora."},
  {"num": 426, "time": "00:31:23,279 --> 00:31:28,580", "arabic": "هُوَ مَوْلَانَا وَعَلَى اللَّهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ", "segs": null, "full_uz": "U bizning Egamiz, mo'minlar Allohgagina tavakkal qilsinlar.", "note": null},
  {"num": 427, "time": "00:31:28,580 --> 00:31:31,279", "arabic": "أَلَسْتَ خَائِفًا مِنَ اللَّهِ؟", "segs": null, "full_uz": "Allohdan qo'rqmaysanmi?", "note": null},
  {"num": 428, "time": "00:31:31,279 --> 00:31:33,480", "arabic": "بَلَى بَلَى", "segs": null, "full_uz": "Albatta, albatta.", "note": null},
  {"num": 429, "time": "00:31:33,480 --> 00:31:38,079", "arabic": "أَمَّا مِنْ غَيْرِهِ فَلَا", "segs": null, "full_uz": "Undan boshqasidan esa yo'q.", "note": null},
  {"num": 430, "time": "00:31:38,079 --> 00:31:39,200", "arabic": "حَسَنًا", "segs": null, "full_uz": "Xo'p.", "note": null},
  {"num": 432, "time": "00:31:42,160 --> 00:31:45,000", "arabic": "فَالسَّيْفُ هُوَ النَّاطِقُ", "segs": null, "full_uz": "Gapiruvchi — qilichdir.", "note": null},
  {"num": 434, "time": "00:31:47,360 --> 00:31:48,839", "arabic": "هَيَّا", "segs": null, "full_uz": "Yur.", "note": null},
  {"num": 435, "time": "00:32:03,480 --> 00:32:13,059", "arabic": "كَانَ اللَّهُ فِي عَوْنِكَ أَيُّهَا الشَّافِعِيُّ", "segs": null, "full_uz": "Alloh sizga yordamchi bo'lsin, ey Shofi'iy.", "note": null},
  {"num": 436, "time": "00:32:13,059 --> 00:32:15,299", "arabic": "كَانَ اللَّهُ فِي عَوْنِكَ", "segs": null, "full_uz": "Alloh sizga yordamchi bo'lsin.", "note": null},
  {"num": 437, "time": "00:32:33,480 --> 00:32:36,960", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
  {"num": 438, "time": "00:32:36,960 --> 00:32:39,920", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Sizga ham salom, Allohning rahmati va barakoti bo'lsin.", "note": null},
  {"num": 439, "time": "00:32:39,920 --> 00:32:44,140", "arabic": "لَقَدْ فَكَّرْتُ فِيمَا أَرَدْتَهُ عَلَيَّ", "segs": null, "full_uz": "Mendan xohlagan narsang haqida o'yladim.", "note": null},
  {"num": 440, "time": "00:32:44,140 --> 00:32:46,480", "arabic": "ثُمَّ؟", "segs": null, "full_uz": "Xo'sh?", "note": null},
  {"num": 441, "time": "00:32:46,480 --> 00:32:47,680", "arabic": "أَنَا رَهْنُ أَمْرِكَ", "segs": null, "full_uz": "Men buyrug'ingizga tayyorman.", "note": null},
  {"num": 442, "time": "00:32:47,680 --> 00:32:51,259", "arabic": "إِذَنِ اعْتَبِرْ نَفْسَكَ مِنَ السَّاعَةِ مَسْؤُولًا مِنِّي", "segs": null, "full_uz": "Unda o'zingni shu soatdan boshlab mening topshirig'im ostida deb bil.", "note": null},
  {"num": 443, "time": "00:32:51,259 --> 00:32:52,440", "arabic": "وَلَكِنْ", "segs": null, "full_uz": "Lekin.", "note": null},
  {"num": 445, "time": "00:32:55,059 --> 00:32:55,059", "arabic": "لَا لَا", "segs": null, "full_uz": "Yo'q, yo'q.", "note": null},
  {"num": 446, "time": "00:32:55,059 --> 00:32:58,220", "arabic": "أَقْصِدُ مَا هِيَ طَبِيعَةُ الْأَخْبَارِ الَّتِي يَجِبُ أَنْ أَنْقُلَهَا", "segs": null, "full_uz": "Demoqchimanki, qanday xabarlarni yetkazishim kerak?", "note": null},
  {"num": 447, "time": "00:32:58,220 --> 00:33:00,019", "arabic": "أَيُّ خَبَرٍ؟", "segs": null, "full_uz": "Qanday xabar?", "note": null},
  {"num": 448, "time": "00:33:00,019 --> 00:33:01,940", "arabic": "لَا تُفَوِّتْ شَارِدَةً وَلَا وَارِدَةً", "segs": null, "full_uz": "Hech narsani — kichigini ham, kattasini ham — qo'ldan chiqarma.", "note": null},
  {"num": 449, "time": "00:33:01,940 --> 00:33:12,019", "arabic": "أَيُّ حَدَثٍ يَخُصُّ أَمِيرَ الْمُؤْمِنِينَ أَوْ دِينَ الدَّوْلَةِ أَوْ رَجُلًا مِنَ الْحَاشِيَةِ تَنْقُلُهُ إِلَيْهِ", "segs": [{"ar": "أَيُّ حَدَثٍ يَخُصُّ أَمِيرَ الْمُؤْمِنِينَ أَوْ دِينَ الدَّوْلَةِ", "uz": "mo'minlar amiriga yoki davlat diniga tegishli har qanday voqea"}, {"ar": "أَوْ رَجُلًا مِنَ الْحَاشِيَةِ تَنْقُلُهُ إِلَيْهِ", "uz": "yoki saroy a'zolaridan biriga tegishlisini unga yetkazasan"}], "full_uz": "Mo'minlar amiriga, davlat diniga yoki saroy a'zolaridan biriga tegishli har qanday voqeani unga yetkazasan.", "note": null},
  {"num": 450, "time": "00:33:12,019 --> 00:33:16,720", "arabic": "وَبِقَدْرِ أَهَمِّيَّةِ الْخَبَرِ الَّذِي تَنْقُلُهُ تَكُونُ مُكَافَأَتُكَ", "segs": null, "full_uz": "Yetkazgan xabaringning ahamiyatiga qarab mukofoting bo'ladi.", "note": null},
  {"num": 451, "time": "00:33:16,720 --> 00:33:25,400", "arabic": "أَنَا عَلَى يَقِينٍ أَنَّ عَمَلَ صَفِيَّةَ سَوْفَ يُعْجِبُكُمْ", "segs": null, "full_uz": "Ishonchim komilki, Safiyaning ishi sizga yoqadi.", "note": null},
  {"num": 452, "time": "00:33:25,400 --> 00:33:27,580", "arabic": "نَرْجُو ذَلِكَ لِنَرَى", "segs": null, "full_uz": "Umid qilamiz, ko'raylik-chi.", "note": null},
  {"num": 453, "time": "00:33:31,940 --> 00:33:34,940", "arabic": "هَذِهِ هِيَ السَّجَّادَةُ", "segs": null, "full_uz": "Mana bu gilam.", "note": null},
  {"num": 454, "time": "00:33:38,940 --> 00:33:41,940", "arabic": "بَارَكَ اللَّهُ فِيكِ يَا صَفِيَّةُ", "segs": null, "full_uz": "Alloh senga barakot bersin, Safiya.", "note": null},
  {"num": 455, "time": "00:33:41,940 --> 00:33:44,940", "arabic": "مَا أَجْوَدَ الْحِيَاكَةَ وَمَا أَبْدَعَهَا", "segs": null, "full_uz": "To'qish naqadar sifatli va ajoyib!", "note": null},
  {"num": 456, "time": "00:33:44,940 --> 00:33:47,940", "arabic": "اَلْمُهِمُّ أَنْ تُعْجِبَ السَّيِّدَاتِ أَيْضًا", "segs": null, "full_uz": "Muhimi, xonimlarga ham yoqishi.", "note": null},
  {"num": 457, "time": "00:33:47,940 --> 00:33:49,940", "arabic": "كَمْ تَطْلُبِينَ ثَمَنَهَا؟", "segs": null, "full_uz": "Unga qancha narx so'raysan?", "note": null},
  {"num": 458, "time": "00:33:50,940 --> 00:33:52,940", "arabic": "يَكْفِي أَنْ تَنَالَ إِعْجَابَكُمْ", "segs": null, "full_uz": "Sizga yoqishi kifoya.", "note": null},
  {"num": 459, "time": "00:33:52,940 --> 00:33:55,940", "arabic": "هُوَ لَا خِلَافَ بَيْنَنَا عَلَى الثَّمَنِ", "segs": null, "full_uz": "Narx borasida bizning oramizda ixtilof yo'q.", "note": null},
  {"num": 460, "time": "00:33:55,940 --> 00:33:57,940", "arabic": "قُولِي كَمْ ثَمَنُهَا؟", "segs": null, "full_uz": "Ayt-chi, narxi qancha?", "note": null},
  {"num": 461, "time": "00:33:57,940 --> 00:34:03,580", "arabic": "أَنْتُنَّ فِي دَارِي وَلَيْسَ مِنَ الْمُرُوءَةِ أَنْ أُسَاوِمَكُنَّ عَلَى ثَمَنِهَا", "segs": null, "full_uz": "Sizlar mening uyimdasiz, narxi ustida sizlar bilan savdolashish mardlikdan emas.", "note": null},
  {"num": 462, "time": "00:34:03,580 --> 00:34:05,980", "arabic": "سَأَتْرُكُ لَكُنَّ تَقْدِيرَ الثَّمَنِ", "segs": null, "full_uz": "Narxni belgilashni sizlarga qoldiraman.", "note": null},
  {"num": 463, "time": "00:34:05,980 --> 00:34:10,639", "arabic": "أَقَلُّ جَوْدَةً مِنْهَا فِي السُّوقِ تُبَاعُ بِعِشْرِينَ دِرْهَمًا", "segs": null, "full_uz": "Undan sifatan pastroqlari bozorda yigirma dirhamga sotiladi.", "note": null},
  {"num": 464, "time": "00:34:10,639 --> 00:34:17,300", "arabic": "وَأَظُنُّهَا تَسْتَحِقُّ خَمْسَةً وَعِشْرِينَ دِرْهَمًا يَكْفِي أَنَّهَا مِنْ صُنْعِ صَفِيَّةَ", "segs": null, "full_uz": "Menimcha, bu yigirma besh dirhamga arziydi, Safiyaning qo'l ishi bo'lishining o'zi yetarli.", "note": null},
  {"num": 465, "time": "00:34:17,300 --> 00:34:20,039", "arabic": "أَلَيْسَ هَذَا كَثِيرًا؟", "segs": null, "full_uz": "Bu ko'p emasmi?", "note": null},
  {"num": 466, "time": "00:34:20,039 --> 00:34:24,240", "arabic": "لَا لَيْسَ كَثِيرًا لَقَدْ عَمِلَتْ فِيهَا أَيَّامًا وَلَيَالِيَ", "segs": null, "full_uz": "Yo'q, ko'p emas, u buning ustida kunlar va tunlar mehnat qildi.", "note": null},
  {"num": 467, "time": "00:34:24,239 --> 00:34:36,439", "arabic": "اَلسَّلَامُ عَلَى أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Mo'minlar amiriga salom bo'lsin.", "note": null},
  {"num": 468, "time": "00:34:36,439 --> 00:34:38,319", "arabic": "وَعَلَيْكَ السَّلَامُ يَا مَسْرُورُ", "segs": null, "full_uz": "Va senga ham salom bo'lsin, Masrur.", "note": null},
  {"num": 469, "time": "00:34:38,319 --> 00:34:39,519", "arabic": "مَا وَرَاءَكَ؟", "segs": null, "full_uz": "Nima xabaring bor?", "note": null},
  {"num": 470, "time": "00:34:39,519 --> 00:34:41,519", "arabic": "اَلسُّجَنَاءُ الَّذِينَ طَلَبْتَ يَا مَوْلَايَ", "segs": null, "full_uz": "Siz talab qilgan mahbuslar, xo'jayinim.", "note": null},
  {"num": 471, "time": "00:34:41,519 --> 00:34:42,879", "arabic": "أَدْخِلْهُمْ", "segs": null, "full_uz": "Ularni kiritgin.", "note": null},
  {"num": 472, "time": "00:34:49,879 --> 00:34:52,639", "arabic": "اَلسَّلَامُ عَلَى أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Mo'minlar amiriga salom bo'lsin.", "note": null},
  {"num": 473, "time": "00:34:52,639 --> 00:34:58,699", "arabic": "وَعَلَيْكَ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Senga ham salom, Allohning rahmati va barakoti bo'lsin.", "note": null},
  {"num": 474, "time": "00:35:22,639 --> 00:35:31,639", "arabic": "أَنْتَ مُحَمَّدُ بْنُ إِدْرِيسَ الشَّافِعِيُّ؟", "segs": null, "full_uz": "Sen Muhammad ibn Idris ash-Shofi'iysanmi?", "note": null},
  {"num": 475, "time": "00:35:31,639 --> 00:35:32,799", "arabic": "أَجَلْ يَا مَوْلَايَ", "segs": null, "full_uz": "Ha, xo'jayinim.", "note": null},
  {"num": 477, "time": "00:35:37,639 --> 00:35:44,639", "arabic": "لِمَاذَا شَقَقْتَ عَصَا الطَّاعَةِ وَخَرَجْتَ عَلَى أَمِيرِ الْمُؤْمِنِينَ؟", "segs": null, "full_uz": "Nega itoat asosini sindirib, mo'minlar amiriga qarshi chiqding?", "note": "«شَقَّ عَصَا الطَّاعَةِ» — itoatdan chiqmoq ma'nosidagi ibora."},
  {"num": 478, "time": "00:35:46,719 --> 00:35:51,379", "arabic": "اَلْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ الْأَمِينِ", "segs": null, "full_uz": "Barcha olamlarning Robbisi Allohga hamd bo'lsin, ishonchli Payg'ambarga salovot va salom bo'lsin.", "note": null},
  {"num": 479, "time": "00:35:51,380 --> 00:35:54,559", "arabic": "أَمَّا بَعْدُ", "segs": null, "full_uz": "Ammo ba'd (bundan keyin).", "note": "Nutqni davom ettirishda ishlatiladigan an'anaviy ibora."},
  {"num": 480, "time": "00:35:54,559 --> 00:35:59,480", "arabic": "لَقَدْ مَنَّ اللَّهُ عَلَيْكُمْ يَا بَنِي الْعَبَّاسِ بِالْمُلْكِ وَالْعِلْمِ", "segs": null, "full_uz": "Alloh sizlarga, ey Abbosiylar, mulk va ilm bilan in'om qildi.", "note": null},
  {"num": 481, "time": "00:35:59,480 --> 00:36:03,579", "arabic": "فَقَابَلْتُمْ هَذِهِ الْمِنَّةَ بِالْإِحْسَانِ وَالشُّكْرِ", "segs": null, "full_uz": "Sizlar bu ne'matga ehson va shukr bilan javob qaytardingiz.", "note": null},
  {"num": 482, "time": "00:36:03,579 --> 00:36:07,880", "arabic": "أَحْسَنْتُمْ إِلَى رَبِّ الْعِبَادِ وَإِلَى الْعِبَادِ", "segs": null, "full_uz": "Bandalar Robbisiga ham, bandalarga ham yaxshilik qildingiz.", "note": null},
  {"num": 483, "time": "00:36:07,880 --> 00:36:11,140", "arabic": "فَخَضَعَتْ لِحُكْمِكُمُ الْبِلَادُ", "segs": null, "full_uz": "Shu tufayli mamlakatlar sizning hukmingizga bo'ysundi.", "note": null},
  {"num": 484, "time": "00:36:11,140 --> 00:36:15,119", "arabic": "رَفَعْتُمْ شَأْنَ السُّنَّةِ وَعُلَمَائِهَا", "segs": null, "full_uz": "Sizlar sunnat va uning olimlarining martabasini yuksaltirdingiz.", "note": null},
  {"num": 485, "time": "00:36:15,119 --> 00:36:16,980", "arabic": "فَرَفَعَ اللَّهُ شَأْنَكُمْ", "segs": null, "full_uz": "Shunga ko'ra Alloh sizning martabangizni yuksaltirdi.", "note": null},
  {"num": 486, "time": "00:36:16,980 --> 00:36:20,280", "arabic": "وَدَحَرْتُمْ أَهْلَ الضَّلَالِ وَالْبِدَعِ", "segs": null, "full_uz": "Va adashgan va bid'atchilarni mag'lub etdingiz.", "note": null},
  {"num": 487, "time": "00:36:20,280 --> 00:36:23,080", "arabic": "فَدَحَرَ اللَّهُ عَدُوَّكُمْ", "segs": null, "full_uz": "Shunga ko'ra Alloh dushmaningizni mag'lub etdi.", "note": null},
  {"num": 488, "time": "00:36:23,080 --> 00:36:26,400", "arabic": "وَلَكِنْ يَا مَوْلَايَ", "segs": null, "full_uz": "Lekin, xo'jayinim.", "note": null},
  {"num": 489, "time": "00:36:26,400 --> 00:36:29,440", "arabic": "مِمَّا يَثْلِمُ الْمُلْكَ الْمَتِينَ", "segs": null, "full_uz": "Mustahkam podsholikka putur yetkazadigan narsalardan biri.", "note": null},
  {"num": 490, "time": "00:36:29,440 --> 00:36:31,580", "arabic": "وَيَهُزُّهُ بَعْدَ التَّمْكِينِ", "segs": null, "full_uz": "Va uni mustahkamlangandan keyin larzaga soladi.", "note": null},
  {"num": 491, "time": "00:36:31,580 --> 00:36:33,940", "arabic": "أَخْذُ النَّاسِ بِالرَّيْبِ وَالشُّكُوكِ", "segs": null, "full_uz": "Odamlarni shubha va gumon asosida jazolash.", "note": null},
  {"num": 492, "time": "00:36:33,940 --> 00:36:37,620", "arabic": "وَإِذَا كَانَ هَذَا سَائِغًا فِي بِدَايَةِ دَوْلَتِكُمْ", "segs": null, "full_uz": "Agar bu davlatingiz boshida joiz bo'lgan bo'lsa ham.", "note": null},
  {"num": 493, "time": "00:36:37,620 --> 00:36:39,600", "arabic": "فَلَيْسَ لَهُ الْآنَ مِنْ مُسَوِّغٍ", "segs": null, "full_uz": "Hozir uning uchun hech qanday asos yo'q.", "note": null},
  {"num": 494, "time": "00:36:39,600 --> 00:36:41,240", "arabic": "وَقَدِ اسْتَقَرَّ مُلْكُكُمْ", "segs": null, "full_uz": "Podsholigingiz mustahkamlandi.", "note": null},
  {"num": 495, "time": "00:36:41,240 --> 00:36:43,040", "arabic": "وَثَبَتَ النَّاسُ عَلَى الطَّاعَةِ", "segs": null, "full_uz": "Va odamlar itoatda mustahkam qoldi.", "note": null},
  {"num": 496, "time": "00:36:43,040 --> 00:36:49,100", "arabic": "إِنَّ اللَّهَ يَا مَوْلَايَ أَمَرَ بِالْعَدْلِ وَبِالْحُكْمِ فِيهِ", "segs": null, "full_uz": "Alloh, xo'jayinim, adolat va u bilan hukm qilishni buyurgan.", "note": null},
  {"num": 497, "time": "00:36:49,099 --> 00:36:55,779", "arabic": "إِذْ قَالَ وَإِذَا حَكَمْتُمْ بَيْنَ النَّاسِ أَنْ تَحْكُمُوا بِالْعَدْلِ", "segs": null, "full_uz": "Chunki U aytdi: «Va odamlar orasida hukm qilsangiz, adolat bilan hukm qiling».", "note": "Qur'ondagi (Niso, 58-oyat) ma'nosiga ishora."},
  {"num": 498, "time": "00:36:55,779 --> 00:37:02,500", "arabic": "وَقَدْ نَصَحْتُ فِي هَذَا بَعْضًا مِمَّنْ وَلَّيْتَهُمْ أَمْرَ الْمُسْلِمِينَ", "segs": null, "full_uz": "Bu haqda musulmonlar ishiga tayinlagan ba'zi kishilaringizga nasihat qildim.", "note": null},
  {"num": 499, "time": "00:37:02,500 --> 00:37:05,779", "arabic": "فَمَا كَانَ مِنْهُمْ إِلَّا أَنْ رَمَوْنِي بِأَشْنَعِ التُّهَمِ", "segs": null, "full_uz": "Ular esa faqat meni eng qabih ayblovlar bilan tuhmat qilishdi.", "note": null},
  {"num": 500, "time": "00:37:05,779 --> 00:37:10,500", "arabic": "وَدَفَعُوا بِي إِلَيْكُمْ مَعَ تَلَامِذَةِ هَؤُلَاءِ مُقَيَّدِينَ مُكَبَّلِينَ", "segs": null, "full_uz": "Va meni bu shogirdlar bilan birga qo'l-oyoqlarim bog'liq holda sizga jo'natdilar.", "note": null},
  {"num": 501, "time": "00:37:10,500 --> 00:37:12,980", "arabic": "وَإِلَيْكُمُ الْأَمْرُ يَا مَوْلَايَ", "segs": null, "full_uz": "Ish endi sizga bog'liq, xo'jayinim.", "note": null},
  {"num": 502, "time": "00:37:12,980 --> 00:37:16,259", "arabic": "فَاحْكُمْ بِمَا أَرَاكَ اللَّهُ", "segs": null, "full_uz": "Alloh sizga ko'rsatgan narsa bilan hukm qiling.", "note": "Qur'ondagi (Niso, 105-oyat) ma'nosiga ishora."},
  {"num": 503, "time": "00:37:16,260 --> 00:37:20,160", "arabic": "وَلَا تَكُنْ لِلْخَائِنِينَ خَصِيمًا", "segs": null, "full_uz": "Va xoinlarga yoqlovchi bo'lmang.", "note": "Qur'ondan (Niso, 105-oyat) to'g'ridan-to'g'ri iqtibos."},
  {"num": 504, "time": "00:37:43,260 --> 00:37:45,400", "arabic": "تَقْصِدُ وَلِيَّنَا عَلَى الْيَمَنِ", "segs": null, "full_uz": "Yaman ustidan tayinlangan hokimimizni nazarda tutyapsanmi?", "note": null},
  {"num": 505, "time": "00:37:45,400 --> 00:37:51,000", "arabic": "أَنَا لَا أَرْمِي أَحَدًا بِغَيْرِ حُجَّةٍ أَوْ دَلِيلٍ يَا مَوْلَايَ", "segs": null, "full_uz": "Men hech kimni dalilsiz ayblamayman, xo'jayinim.", "note": null},
  {"num": 506, "time": "00:37:51,000 --> 00:37:53,840", "arabic": "وَمَا قَصَدْتُ رَجُلًا بِعَيْنِهِ", "segs": null, "full_uz": "Va aniq bir kishini nazarda tutmadim.", "note": null},
  {"num": 507, "time": "00:37:53,840 --> 00:37:57,920", "arabic": "لَمَّا قَصَدْتُ ذَلِكَ الَّذِي بَعَثَ إِلَيْكُمْ", "segs": null, "full_uz": "Balki sizga xat jo'natgan o'sha kishini nazarda tutgandirman.", "note": null},
  {"num": 508, "time": "00:37:57,920 --> 00:38:02,519", "arabic": "بِتِلْكَ الْوِشَايَةِ الْكَاذِبَةِ كَائِنًا مَنْ كَانَ", "segs": null, "full_uz": "O'sha yolg'on tuhmat bilan, kim bo'lishidan qat'i nazar.", "note": null},
  {"num": 509, "time": "00:38:02,519 --> 00:38:07,300", "arabic": "أَمَّا أَنَا فَرَجُلٌ أَمْضَى عُمْرَهُ", "segs": null, "full_uz": "Men esa umrini o'tkazgan bir odamman.", "note": null},
  {"num": 510, "time": "00:38:07,300 --> 00:38:11,280", "arabic": "فِي طَلَبِ الْعِلْمِ وَمُدَارَسَةِ كِتَابِ اللَّهِ عَزَّ وَجَلَّ", "segs": null, "full_uz": "Ilm talab qilish va Allohning Kitobini mutolaa qilish yo'lida.", "note": null},
  {"num": 511, "time": "00:38:11,280 --> 00:38:14,619", "arabic": "وَلَيْسَ لِي فِي شُؤُونِ الْحُكْمِ وَالسِّيَاسَةِ", "segs": null, "full_uz": "Va hukm va siyosat ishlarida mening aloqam yo'q.", "note": null},
  {"num": 512, "time": "00:38:14,619 --> 00:38:17,440", "arabic": "فَهِيَ لَهَا رِجَالَاتُهَا الْمُحَنَّكُونَ", "segs": null, "full_uz": "Uning o'ziga xos tajribali odamlari bor.", "note": null},
  {"num": 513, "time": "00:38:17,440 --> 00:38:22,400", "arabic": "أَمَّا مَنِ ادَّعَى أَنَّنِي أَنْصُرُ الطَّالِبِيِّينَ عَلَى أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Meni Tolibiylarni mo'minlar amiriga qarshi qo'llab-quvvatlaydi, deb da'vo qilganlarga kelsak.", "note": null},
  {"num": 514, "time": "00:38:22,400 --> 00:38:24,059", "arabic": "فَقَدْ كَذَبَ وَاللَّهِ", "segs": null, "full_uz": "Alloh haqqi, u yolg'on gapirgan.", "note": null},
  {"num": 515, "time": "00:38:24,059 --> 00:38:29,719", "arabic": "فَأَمِيرُ الْمُؤْمِنِينَ وَالطَّالِبِيُّونَ يَمُتُّونَ إِلَيَّ بِذَاتِ الصِّلَةِ", "segs": null, "full_uz": "Mo'minlar amiri ham, Tolibiylar ham menga bir xil qarindoshlik rishtasi bilan bog'liq.", "note": null},
  {"num": 516, "time": "00:38:29,719 --> 00:38:34,679", "arabic": "هَذَا أَخِي وَهَذَا ابْنُ عَمِّي وَمَا أَنَا بِنَاصِرِ أَحَدِهِمَا عَلَى الْآخَرِ", "segs": null, "full_uz": "Bu — mening akam, bu esa — amakivachcham, men ulardan birini ikkinchisiga qarshi qo'llamayman.", "note": null},
  {"num": 517, "time": "00:38:34,679 --> 00:38:38,019", "arabic": "وَمَنْ كَانَ يَدَّعِي غَيْرَ ذَلِكَ", "segs": null, "full_uz": "Va kim boshqacha da'vo qilsa.", "note": null},
  {"num": 518, "time": "00:38:38,019 --> 00:38:42,839", "arabic": "فَلْيَأْتِ بِدَلِيلِهِ إِنْ كَانَ صَادِقًا فِيمَا يَزْعُمُ", "segs": null, "full_uz": "Agar da'vosida rost bo'lsa, dalilini keltirsin.", "note": null},
  {"num": 519, "time": "00:38:42,840 --> 00:38:47,300", "arabic": "أَمَّا يَا مَوْلَايَ مُحَاكَمَةُ الْقُلُوبِ وَالنِّيَّاتِ", "segs": null, "full_uz": "Qalblar va niyatlarni hukm qilishga kelsak esa, xo'jayinim.", "note": null},
  {"num": 520, "time": "00:38:47,300 --> 00:38:52,960", "arabic": "فَهِيَ مِنْ شَأْنِ عَالِمِ الْغَيْبِ رَبِّ الْأَرْضِ وَالسَّمَاوَاتِ", "segs": null, "full_uz": "Bu — g'aybni Biluvchi, yer va osmonlarning Robbisiga tegishli ishdir.", "note": null},
  {"num": 521, "time": "00:38:52,960 --> 00:38:56,740", "arabic": "لَا مِنْ شَأْنِ الْقُضَاةِ أَوِ الْوُلَاةِ", "segs": null, "full_uz": "Qozilar yoki hukmdorlarga tegishli emas.", "note": null},
  {"num": 522, "time": "00:39:04,519 --> 00:39:09,519", "arabic": "إِنَّمَا يُحَاكِمُ الْقُلُوبَ مَنْ هُوَ أَدْرَى بِمَا تُكِنُّ الْقُلُوبُ", "segs": null, "full_uz": "Qalblarni faqat qalblarda yashiringan narsani eng yaxshi biluvchi Zot hukm qiladi.", "note": null},
  {"num": 523, "time": "00:39:09,519 --> 00:39:12,519", "arabic": "مَا رَأْيُ قَاضِي قُضَاتِنَا بِهَؤُلَاءِ الرِّجَالِ؟", "segs": null, "full_uz": "Bosh qozimizning bu kishilar haqidagi fikri qanday?", "note": null},
  {"num": 524, "time": "00:39:12,840 --> 00:39:17,079", "arabic": "إِنْ أَذِنَ لِي أَمِيرُ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Agar mo'minlar amiri menga ruxsat bersa.", "note": null},
  {"num": 525, "time": "00:39:17,079 --> 00:39:22,680", "arabic": "لَقَدْ نَظَرْتُ فِي أَمْرِ هَذَا الرَّجُلِ وَهَؤُلَاءِ الْأَرْبَعِ", "segs": null, "full_uz": "Men bu kishi va bu to'rt nafarning ishini ko'rib chiqdim.", "note": null},
  {"num": 526, "time": "00:39:22,680 --> 00:39:25,360", "arabic": "فَلَمْ أَجِدْ دَلِيلًا وَاحِدًا يُدِينُهُمْ", "segs": null, "full_uz": "Va ularni ayblovchi bironta ham dalil topmadim.", "note": null},
  {"num": 527, "time": "00:39:25,360 --> 00:39:32,140", "arabic": "وَقَدْ أَنْكَرُوا كُلَّ مَا نُسِبَ إِلَيْهِمْ خِلَافًا لِمَنْ حَكَمْنَا بِهِمْ بِحُكْمِ اللَّهِ", "segs": null, "full_uz": "Ular o'zlariga nisbat berilgan hamma narsani inkor etishdi, Alloh hukmi bilan hukm qilganlarimizdan farqli o'laroq.", "note": null},
  {"num": 528, "time": "00:39:32,140 --> 00:39:35,960", "arabic": "وَأُشْهِدُ اللَّهَ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ", "segs": null, "full_uz": "G'ayb va shohidlikni Biluvchi Allohni guvoh qilaman.", "note": null},
  {"num": 529, "time": "00:39:35,960 --> 00:39:38,440", "arabic": "أَنِّي أَعْرِفُ هَذَا الرَّجُلَ جَيِّدًا", "segs": null, "full_uz": "Men bu kishini yaxshi bilaman.", "note": null},
  {"num": 530, "time": "00:39:38,440 --> 00:39:42,360", "arabic": "لَكِنِّي لَمْ أُذَكِّرْهُ بِنَفْسِي", "segs": null, "full_uz": "Lekin men o'zim unga eslatmadim.", "note": null},
  {"num": 531, "time": "00:39:42,360 --> 00:39:45,640", "arabic": "وَهُوَ كَذَلِكَ لَمْ يَتَذَكَّرْنِي", "segs": null, "full_uz": "U ham meni eslamadi.", "note": null},
  {"num": 532, "time": "00:39:45,640 --> 00:39:51,340", "arabic": "أَلَا فَلْيَعْلَمِ الْقَاضِي مُحَمَّدُ بْنُ الْحَسَنِ الشَّيْبَانِيُّ", "segs": null, "full_uz": "Bilib qo'ysinki, qozi Muhammad ibn Hasan ash-Shayboniy.", "note": null},
  {"num": 533, "time": "00:39:51,340 --> 00:39:56,240", "arabic": "صَاحِبُ أَبِي حَنِيفَةَ النُّعْمَانِ وَتِلْمِيذُهُ النَّجِيبُ", "segs": null, "full_uz": "Abu Hanifa an-Nu'monning safdoshi va uning aqlli shogirdi.", "note": null},
  {"num": 534, "time": "00:39:56,240 --> 00:39:59,539", "arabic": "أَنَّنِي عَرَفْتُهُ مُنْذُ رَأَيْتُهُ", "segs": null, "full_uz": "Men uni ko'rganimdan beri taniganman.", "note": null},
  {"num": 535, "time": "00:39:59,539 --> 00:40:03,360", "arabic": "وَلَكِنْ لَمْ أَشَأْ أَنْ أُذَكِّرَهُ بِنَفْسِي", "segs": null, "full_uz": "Lekin o'zimni unga eslatishni istamadim.", "note": null},
  {"num": 536, "time": "00:40:04,220 --> 00:40:06,280", "arabic": "كَيْ يَكُونَ عَادِلًا أَمَامَ اللَّهِ", "segs": null, "full_uz": "Alloh oldida odil bo'lishi uchun.", "note": null},
  {"num": 537, "time": "00:40:06,280 --> 00:40:09,019", "arabic": "وَأَمَامَ أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Va mo'minlar amiri oldida.", "note": null},
  {"num": 538, "time": "00:40:12,360 --> 00:40:13,559", "arabic": "مَسْرُورُ", "segs": null, "full_uz": "Masrur!", "note": null},
  {"num": 539, "time": "00:40:13,559 --> 00:40:14,900", "arabic": "مَوْلَايَ", "segs": null, "full_uz": "Xo'jayinim.", "note": null},
  {"num": 540, "time": "00:40:14,900 --> 00:40:20,500", "arabic": "أَعِدِ السُّجَنَاءَ إِلَى مَحْبَسِهِمْ حَتَّى نَنْظُرَ فِي أَمْرِهِمْ", "segs": null, "full_uz": "Mahbuslarni ularning zindoniga qaytar, toki ishlarini ko'rib chiqquncha.", "note": null},
  {"num": 541, "time": "00:40:20,500 --> 00:40:21,920", "arabic": "اَلسَّمْعُ وَالطَّاعَةُ", "segs": null, "full_uz": "Eshitish va bo'ysunish bor.", "note": null},
  {"num": 542, "time": "00:40:21,920 --> 00:40:23,240", "arabic": "هَيَّا", "segs": null, "full_uz": "Yur.", "note": null},
  {"num": 543, "time": "00:40:23,240 --> 00:40:37,500", "arabic": "مِنْ أَيْنَ تَعْرِفُهُ يَا أَبَا الْحَسَنِ؟", "segs": null, "full_uz": "Uni qayerdan bilasiz, Abul-Hasan?", "note": null},
  {"num": 544, "time": "00:40:37,500 --> 00:40:39,700", "arabic": "لِي بِهِ مَعْرِفَةٌ سَابِقَةٌ يَا مَوْلَايَ", "segs": null, "full_uz": "Uni ilgaridan tanirdim, xo'jayinim.", "note": null},
  {"num": 545, "time": "00:40:39,700 --> 00:40:42,039", "arabic": "اِلْتَقَيْتُهُ بِالْحِجَازِ", "segs": null, "full_uz": "Uning bilan Hijozda uchrashgandim.", "note": null},
  {"num": 546, "time": "00:40:42,039 --> 00:40:45,739", "arabic": "وَهُوَ مِنْ أَلْمَعِ طَلَبَةِ الْإِمَامِ مَالِكٍ رَحِمَهُ اللَّهُ", "segs": null, "full_uz": "U imom Molik — Alloh unga rahmat qilsin — ning eng zukko shogirdlaridan.", "note": null},
  {"num": 547, "time": "00:40:45,739 --> 00:40:51,639", "arabic": "مِنْ أَلْمَعِ طَلَبَةِ الْإِمَامِ مَالِكٍ رَحِمَهُ اللَّهُ؟", "segs": null, "full_uz": "Imom Molikning eng zukko shogirdlaridanmi?", "note": null},
  {"num": 548, "time": "00:40:51,639 --> 00:40:51,940", "arabic": "نَعَمْ", "segs": null, "full_uz": "Ha.", "note": null},
  {"num": 549, "time": "00:40:51,940 --> 00:40:55,019", "arabic": "إِذَنْ فَأَنْتَ تَعْرِفُهُ جَيِّدًا", "segs": null, "full_uz": "Demak, uni yaxshi bilasiz.", "note": null},
  {"num": 550, "time": "00:40:55,019 --> 00:40:55,400", "arabic": "نَعَمْ", "segs": null, "full_uz": "Ha.", "note": null},
  {"num": 551, "time": "00:40:55,400 --> 00:40:57,900", "arabic": "هُوَ ذَكِيٌّ أَلْمَعِيٌّ", "segs": null, "full_uz": "U aqlli va zukko.", "note": null},
  {"num": 552, "time": "00:40:57,900 --> 00:41:00,579", "arabic": "وَلَهُ مِنَ الْعِلْمِ وَالْفَضْلِ مَحَلٌّ كَبِيرٌ", "segs": null, "full_uz": "Uning ilm va fazilatda katta o'rni bor.", "note": null},
  {"num": 553, "time": "00:41:00,579 --> 00:41:04,840", "arabic": "وَلَيْسَ الَّذِي ادُّعِيَ عَلَيْهِ مِنْ شَأْنِهِ أَوْ مِنْ شَوَاغِلِهِ", "segs": null, "full_uz": "Unga nisbat berilgan narsa uning ishi yoki mashg'ulotlaridan emas.", "note": null},
  {"num": 554, "time": "00:41:04,840 --> 00:41:09,039", "arabic": "وَلَمْ أَرَهُ يَوْمًا يَتَكَلَّمُ عَنْ أَمِيرِ الْمُؤْمِنِينَ إِلَّا بِالْخَيْرِ", "segs": null, "full_uz": "Uni hech qachon mo'minlar amiri haqida faqat yaxshilik bilan gapirmaganini ko'rmaganman.", "note": null},
  {"num": 555, "time": "00:41:09,039 --> 00:41:14,199", "arabic": "وَأَحْسَبُ أَنَّ مَا جَاءَكَ عَنْهُ مَحْضُ كَذِبٍ وَتَلْفِيقٍ", "segs": null, "full_uz": "Va sizga u haqida kelgan narsa sof yolg'on va to'qima deb o'ylayman.", "note": null},
  {"num": 556, "time": "00:41:14,199 --> 00:41:15,880", "arabic": "كَمَا قَالَ وَبَيَّنَ", "segs": null, "full_uz": "U aytgan va bayon qilganidek.", "note": null},
  {"num": 557, "time": "00:41:15,880 --> 00:41:17,279", "arabic": "إِلَّا إِنْ كَانَ", "segs": null, "full_uz": "Faqat agar bo'lsa.", "note": null},
  {"num": 558, "time": "00:41:17,279 --> 00:41:20,079", "arabic": "ثَمَّ دَلِيلٌ قَاطِعٌ بِذَلِكَ", "segs": null, "full_uz": "Bunga qat'iy dalil bo'lsagina.", "note": null},
  {"num": 559, "time": "00:41:20,079 --> 00:41:22,179", "arabic": "وَلَمْ أَجِدْهُ يَا مَوْلَايَ", "segs": null, "full_uz": "Va men uni topmadim, xo'jayinim.", "note": null}
];
if (typeof module !== "undefined" && module.exports) {
  module.exports = lessons;
}